// Cyrus engine core: the plan-tier gate for custom assets (MASTER-PLAN section 2, owner decisions).
//   free, katara -> no asset studios, no asset generation
//   saka         -> SOUND (Sound Studio + Sound Library)
//   all          -> SOUND + TEXTURE (the top plan; it includes the Yakko model)
// Tiers are cumulative. The gate applies only to CREATING or EDITING asset content (a studio, a library pick, an
// upload, or Cyrus generating it automatically inside a build). Keeping, installing, rebuilding unchanged,
// exporting, importing your own mod and composing Mod Packs are NEVER gated. An unknown plan or token state
// denies creation (fail closed) but never denies keep/install/export.
// Pure + client-safe; the server must call it again on every request (the UI check is only a hint).
import type { AssetKind, AssetSource, ModSpec } from "./spec";
import { ASSET_KINDS } from "./spec";

export const ASSET_PLANS = ["free", "katara", "saka", "all"] as const;
export type AssetPlan = (typeof ASSET_PLANS)[number];
const RANK: Record<AssetPlan, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const PLAN_LABEL: Record<AssetPlan, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

/**
 * THE one place that reconciles plan spellings. The token economy calls the top plan `all`
 * (lib/cyrus/tokens/config.ts TOKEN_TIERS); the UI and the model list call it after its top model, Yakko.
 * Anything else (null, a typo, a future plan) is unknown -> null, and callers fail closed.
 */
export function normalizePlan(raw: unknown): AssetPlan | null {
  if (typeof raw !== "string") return null;
  const v = raw.trim().toLowerCase();
  if (v === "all" || v === "yakko" || v === "all models") return "all";
  if (v === "free" || v === "katara" || v === "saka") return v;
  return null;
}

/** Plan from a token state (lib/cyrus/tokens/view.ts TokenState) or anything with a `tier`. Missing state -> null (unknown). */
export const planFromTokenState = (state: { tier?: unknown } | null | undefined): AssetPlan | null => normalizePlan(state?.tier);

/**
 * Cheapest plan that may create/edit each kind. `model` and `ui` are visual assets drawn with the texture tools,
 * so they follow the Texture Studio (top plan).
 */
export const ASSET_MIN_PLAN: Readonly<Record<AssetKind, AssetPlan>> = { sound: "saka", texture: "all", model: "all", ui: "all" };

export const ASSET_OPS = ["create", "edit", "keep", "install", "export", "rebuild", "import", "compose"] as const;
export type AssetOp = (typeof ASSET_OPS)[number];
export const GATED_OPS: readonly AssetOp[] = ["create", "edit"];

export type AssetDecision =
  | { ok: true }
  | { ok: false; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

const KIND_WORD: Record<AssetKind, string> = { sound: "custom sounds", texture: "custom textures", model: "custom models", ui: "custom menu and HUD art" };

export function canAsset(plan: unknown, kind: AssetKind, op: AssetOp): AssetDecision {
  if (!(ASSET_OPS as readonly string[]).includes(op)) return { ok: false, code: "bad_request", reason: `unknown asset operation ${String(op)}` };
  if (!GATED_OPS.includes(op)) return { ok: true }; // keep / install / export / rebuild / import / compose: never gated
  if (!(ASSET_KINDS as readonly string[]).includes(kind)) return { ok: false, code: "bad_request", reason: `unknown asset kind ${String(kind)}` };
  const needs = ASSET_MIN_PLAN[kind];
  const p = normalizePlan(plan);
  if (!p) return { ok: false, code: "plan_unknown", needs, reason: `We couldn't confirm your Cyrus plan, so ${KIND_WORD[kind]} can't be created or edited right now.` };
  if (RANK[p] < RANK[needs]) return { ok: false, code: "asset_locked", needs, reason: `Creating or editing ${KIND_WORD[kind]} needs the ${PLAN_LABEL[needs]} plan or higher.` };
  return { ok: true };
}

/** What a spec asset slot asks the engine to do with asset content. */
export function assetOpForSource(source: AssetSource): AssetOp {
  switch (source) {
    case "generate": case "library": case "upload": return "create";
    case "edit": return "edit";
    case "existing": return "keep";
    case "imported": return "import";
    default: return "create"; // unknown source: treat as the gated case
  }
}

export type AssetDenial = { assetId: string; kind: AssetKind; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

/** Every asset slot of a spec the plan may not create/edit (no changes). The build service request runs this too. */
export function gateSpecAssets(spec: Pick<ModSpec, "assets">, plan: unknown): AssetDenial[] {
  const out: AssetDenial[] = [];
  for (const a of spec.assets) {
    const d = canAsset(plan, a.kind, assetOpForSource(a.source));
    if (!d.ok) out.push({ assetId: a.id, kind: a.kind, code: d.code, reason: d.reason, ...(d.needs ? { needs: d.needs } : {}) });
  }
  return out;
}

const FALLBACK: Record<AssetKind, string> = { sound: "a vanilla sound", texture: "a vanilla look", model: "a vanilla model", ui: "plain text and standard menus" };

/**
 * Router downgrade: strip the gated asset slots instead of failing the build, with a customer-visible reason
 * per slot. Requirements stay (the mod still does what was asked, without the custom asset). Pure: returns a copy.
 */
export function downgradeSpecAssets<S extends Pick<ModSpec, "assets">>(spec: S, plan: unknown): { spec: S; removed: AssetDenial[]; notices: string[] } {
  const removed = gateSpecAssets(spec, plan);
  if (!removed.length) return { spec, removed, notices: [] };
  const drop = new Set(removed.map((r) => r.assetId));
  const notices = removed.map((r) => `${r.reason} Cyrus will build "${r.assetId}" with ${FALLBACK[r.kind]} instead.`);
  return { spec: { ...spec, assets: spec.assets.filter((a) => !drop.has(a.id)) }, removed, notices };
}
// Procedural item textures, drawn by CODE (no image generation). The model never writes arbitrary drawing code:
// it writes a small declarative spec (this file's TextureSpec), and Nxeon's own renderer draws it, so the output is
// deterministic, bounded in size and time, and cannot run anything. Pure and dependency-free.

export const TEXTURE_SIZES = [16, 32, 64] as const;
export const MAX_OPS = 400;
export const MAX_PALETTE = 24;

export type Op =
  | { op: "fill"; c: string }
  | { op: "px"; x: number; y: number; c: string }
  | { op: "rect"; x: number; y: number; w: number; h: number; c: string }
  | { op: "line"; x1: number; y1: number; x2: number; y2: number; c: string }
  | { op: "circle"; x: number; y: number; r: number; c: string; ring?: boolean }
  | { op: "poly"; pts: [number, number][]; c: string }
  | { op: "gradient"; x: number; y: number; w: number; h: number; c1: string; c2: string; dir?: "v" | "h" }
  | { op: "noise"; amount: number; seed?: number; x?: number; y?: number; w?: number; h?: number }
  | { op: "shade"; amount?: number }
  | { op: "outline"; c: string };

export type TextureSpec = {
  name: string;
  size: (typeof TEXTURE_SIZES)[number];
  palette: Record<string, string>;
  /** Draw the left half and mirror it to the right. */
  mirror?: boolean;
  ops: Op[];
};

const HEX = /^#[0-9a-fA-F]{6}$/;
const KEY = /^[a-z][a-z0-9_]{0,23}$/;
const NAME = /^[a-z][a-z0-9_]{1,31}$/;

export type Checked = { ok: true; spec: TextureSpec } | { ok: false; error: string };

const num = (v: unknown, lo: number, hi: number) => typeof v === "number" && Number.isFinite(v) && v >= lo && v <= hi;

/** Validate untrusted JSON into a TextureSpec. Every number is range-checked against the canvas, every colour must be in the palette. */
export function checkSpec(raw: unknown): Checked {
  if (!raw || typeof raw !== "object") return { ok: false, error: "texture must be an object" };
  const r = raw as Record<string, unknown>;
  if (typeof r.name !== "string" || !NAME.test(r.name)) return { ok: false, error: "name must be lowercase letters, digits and underscores (2-32 chars)" };
  if (!(TEXTURE_SIZES as readonly number[]).includes(r.size as number)) return { ok: false, error: "size must be 16, 32 or 64" };
  const size = r.size as TextureSpec["size"];
  if (!r.palette || typeof r.palette !== "object") return { ok: false, error: "palette is required" };
  const palette: Record<string, string> = {};
  const entries = Object.entries(r.palette as Record<string, unknown>);
  if (entries.length === 0 || entries.length > MAX_PALETTE) return { ok: false, error: `palette needs 1-${MAX_PALETTE} colours` };
  for (const [k, v] of entries) {
    if (!KEY.test(k)) return { ok: false, error: `bad palette key ${k}` };
    if (typeof v !== "string" || !HEX.test(v)) return { ok: false, error: `palette ${k} must be #rrggbb` };
    palette[k] = v.toLowerCase();
  }
  if (!Array.isArray(r.ops) || r.ops.length === 0 || r.ops.length > MAX_OPS) return { ok: false, error: `ops needs 1-${MAX_OPS} entries` };
  const col = (c: unknown) => typeof c === "string" && c in palette;
  const pos = (v: unknown) => num(v, -size, size * 2);
  const ops: Op[] = [];
  for (const [i, o] of (r.ops as unknown[]).entries()) {
    const at = `ops[${i}]`;
    if (!o || typeof o !== "object") return { ok: false, error: `${at} must be an object` };
    const p = o as Record<string, unknown>;
    switch (p.op) {
      case "fill": if (!col(p.c)) return { ok: false, error: `${at}: unknown colour` }; ops.push({ op: "fill", c: p.c as string }); break;
      case "px": if (!pos(p.x) || !pos(p.y) || !col(p.c)) return { ok: false, error: `${at}: bad px` }; ops.push({ op: "px", x: p.x as number, y: p.y as number, c: p.c as string }); break;
      case "rect": if (![p.x, p.y].every(pos) || !num(p.w, 0, size * 2) || !num(p.h, 0, size * 2) || !col(p.c)) return { ok: false, error: `${at}: bad rect` }; ops.push({ op: "rect", x: p.x as number, y: p.y as number, w: p.w as number, h: p.h as number, c: p.c as string }); break;
      case "line": if (![p.x1, p.y1, p.x2, p.y2].every(pos) || !col(p.c)) return { ok: false, error: `${at}: bad line` }; ops.push({ op: "line", x1: p.x1 as number, y1: p.y1 as number, x2: p.x2 as number, y2: p.y2 as number, c: p.c as string }); break;
      case "circle": if (!pos(p.x) || !pos(p.y) || !num(p.r, 0, size) || !col(p.c)) return { ok: false, error: `${at}: bad circle` }; ops.push({ op: "circle", x: p.x as number, y: p.y as number, r: p.r as number, c: p.c as string, ring: p.ring === true }); break;
      case "poly": {
        if (!Array.isArray(p.pts) || p.pts.length < 3 || p.pts.length > 40 || !col(p.c)) return { ok: false, error: `${at}: poly needs 3-40 points and a colour` };
        const pts: [number, number][] = [];
        for (const q of p.pts as unknown[]) { if (!Array.isArray(q) || q.length !== 2 || !pos(q[0]) || !pos(q[1])) return { ok: false, error: `${at}: bad point` }; pts.push([q[0] as number, q[1] as number]); }
        ops.push({ op: "poly", pts, c: p.c as string }); break;
      }
      case "gradient": if (![p.x, p.y].every(pos) || !num(p.w, 0, size * 2) || !num(p.h, 0, size * 2) || !col(p.c1) || !col(p.c2)) return { ok: false, error: `${at}: bad gradient` }; ops.push({ op: "gradient", x: p.x as number, y: p.y as number, w: p.w as number, h: p.h as number, c1: p.c1 as string, c2: p.c2 as string, dir: p.dir === "h" ? "h" : "v" }); break;
      case "noise": if (!num(p.amount, 0, 60)) return { ok: false, error: `${at}: noise amount 0-60` }; ops.push({ op: "noise", amount: p.amount as number, seed: num(p.seed, 0, 1e9) ? (p.seed as number) : 1, ...(num(p.x, 0, size) && num(p.y, 0, size) && num(p.w, 0, size) && num(p.h, 0, size) ? { x: p.x as number, y: p.y as number, w: p.w as number, h: p.h as number } : {}) }); break;
      case "shade": ops.push({ op: "shade", amount: num(p.amount, 0, 60) ? (p.amount as number) : 28 }); break;
      case "outline": if (!col(p.c)) return { ok: false, error: `${at}: unknown colour` }; ops.push({ op: "outline", c: p.c as string }); break;
      default: return { ok: false, error: `${at}: unknown op ${String(p.op)}` };
    }
  }
  return { ok: true, spec: { name: r.name, size, palette, mirror: r.mirror === true, ops } };
}
// A Minecraft resource pack from validated texture specs: one item model per texture, wired the 1.21.4+ way
// (assets/<ns>/items/<name>.json is what `ItemMeta.setItemModel(new NamespacedKey("<ns>", "<name>"))` points at).
import { createHash } from "node:crypto";
import { checkSpec, type TextureSpec } from "./dsl";
import { encodePng } from "./png";
import { render } from "./render";
import { zip } from "./zip";
import { getVersion, resourcePackFormat } from "../versions/registry";

/** Resource-pack major format for a version, from the version registry. Throws for an unknown/unverified version (never guesses). */
export function packFormatFor(mc: string): number {
  const r = resourcePackFormat(mc);
  if (!r.ok) throw new Error(r.error);
  return r.format.major;
}

export type BuiltPack = { packFormat: number; packClientVerified: boolean; zip: Buffer; sha1: string; bytes: number; files: string[]; textures: { name: string; model: string }[] };

export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; allowPreview?: boolean }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {
  if (!/^[a-z][a-z0-9_]{1,30}$/.test(opts.namespace)) return { ok: false, error: "namespace must be lowercase letters, digits and underscores" };
  if (opts.textures.length === 0 || opts.textures.length > 24) return { ok: false, error: "a pack needs 1-24 textures" };
  const specs: TextureSpec[] = [];
  for (const [i, t] of opts.textures.entries()) { const c = checkSpec(t); if (!c.ok) return { ok: false, error: `texture ${i + 1}: ${c.error}` }; if (specs.some((s) => s.name === c.spec.name)) return { ok: false, error: `duplicate texture name ${c.spec.name}` }; specs.push(c.spec); }
  const ver = getVersion(opts.mcVersion);
  if (ver && ver.status === "preview" && !opts.allowPreview) return { ok: false, error: `${opts.mcVersion} is a preview version: its resource packs are not verified in a real client yet` };
  const pf = resourcePackFormat(opts.mcVersion, { needsItemModels: true });
  if (!pf.ok) return { ok: false, error: pf.error };
  const fmt = pf.format.major;
  const files: { path: string; data: Buffer }[] = [
    { path: "pack.mcmeta", data: Buffer.from(JSON.stringify({ pack: { pack_format: fmt, supported_formats: { min_inclusive: 46, max_inclusive: 999 }, min_format: 46, max_format: 999, description: opts.description.slice(0, 100) } }, null, 2)) },
  ];
  const ns = opts.namespace;
  for (const s of specs) {
    files.push({ path: `assets/${ns}/textures/item/${s.name}.png`, data: encodePng(render(s)) });
    files.push({ path: `assets/${ns}/models/item/${s.name}.json`, data: Buffer.from(JSON.stringify({ parent: "minecraft:item/handheld", textures: { layer0: `${ns}:item/${s.name}` } }, null, 2)) });
    files.push({ path: `assets/${ns}/items/${s.name}.json`, data: Buffer.from(JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${s.name}` } }, null, 2)) });
  }
  const z = zip(files);
  return { ok: true, pack: { packFormat: fmt, packClientVerified: pf.clientVerified, zip: z, sha1: createHash("sha1").update(z).digest("hex"), bytes: z.length, files: files.map((f) => f.path).sort(), textures: specs.map((s) => ({ name: s.name, model: `${ns}:${s.name}` })) } };
}
// Deterministic pixel-art renderer for a validated TextureSpec: RGBA, no anti-aliasing (crisp like game art).
import type { Op, TextureSpec } from "./dsl";

export type Raster = { size: number; px: Uint8ClampedArray };

const rgb = (hex: string): [number, number, number] => [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
const clamp = (v: number) => Math.max(0, Math.min(255, Math.round(v)));

/** Small deterministic PRNG so the same spec always yields the same bytes. */
function rng(seed: number) { let s = (seed >>> 0) || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; }; }

export function render(spec: TextureSpec): Raster {
  const n = spec.size;
  const px = new Uint8ClampedArray(n * n * 4); // transparent
  const P = (k: string) => rgb(spec.palette[k]);
  const set = (x: number, y: number, c: [number, number, number]) => {
    x = Math.round(x); y = Math.round(y);
    if (x < 0 || y < 0 || x >= n || y >= n) return;
    const i = (y * n + x) * 4; px[i] = c[0]; px[i + 1] = c[1]; px[i + 2] = c[2]; px[i + 3] = 255;
  };
  const opaque = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && px[(y * n + x) * 4 + 3] > 0;

  const draw = (o: Op) => {
    switch (o.op) {
      case "fill": { const c = P(o.c); for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) set(x, y, c); break; }
      case "px": set(o.x, o.y, P(o.c)); break;
      case "rect": { const c = P(o.c); for (let y = Math.floor(o.y); y < Math.floor(o.y) + o.h; y++) for (let x = Math.floor(o.x); x < Math.floor(o.x) + o.w; x++) set(x, y, c); break; }
      case "line": {
        const c = P(o.c); let x0 = Math.round(o.x1), y0 = Math.round(o.y1); const x1 = Math.round(o.x2), y1 = Math.round(o.y2);
        const dx = Math.abs(x1 - x0), dy = -Math.abs(y1 - y0), sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1; let err = dx + dy;
        for (let guard = 0; guard < 4096; guard++) { set(x0, y0, c); if (x0 === x1 && y0 === y1) break; const e2 = 2 * err; if (e2 >= dy) { err += dy; x0 += sx; } if (e2 <= dx) { err += dx; y0 += sy; } }
        break;
      }
      case "circle": {
        const c = P(o.c);
        for (let y = Math.floor(o.y - o.r - 1); y <= Math.ceil(o.y + o.r + 1); y++) for (let x = Math.floor(o.x - o.r - 1); x <= Math.ceil(o.x + o.r + 1); x++) {
          const d = Math.hypot(x + 0.5 - o.x, y + 0.5 - o.y);
          if (o.ring ? d <= o.r && d > o.r - 1.2 : d <= o.r) set(x, y, c);
        }
        break;
      }
      case "poly": {
        const c = P(o.c); const ys = o.pts.map((p) => p[1]); const y0 = Math.max(0, Math.floor(Math.min(...ys))), y1 = Math.min(n - 1, Math.ceil(Math.max(...ys)));
        for (let y = y0; y <= y1; y++) {
          const yc = y + 0.5; const xs: number[] = [];
          for (let i = 0; i < o.pts.length; i++) {
            const [ax, ay] = o.pts[i], [bx, by] = o.pts[(i + 1) % o.pts.length];
            if ((ay <= yc && by > yc) || (by <= yc && ay > yc)) xs.push(ax + ((yc - ay) / (by - ay)) * (bx - ax));
          }
          xs.sort((a, b) => a - b);
          for (let k = 0; k + 1 < xs.length; k += 2) for (let x = Math.ceil(xs[k] - 0.5); x <= Math.floor(xs[k + 1] - 0.5); x++) set(x, y, c);
        }
        break;
      }
      case "gradient": {
        const a = P(o.c1), b = P(o.c2);
        for (let y = Math.floor(o.y); y < Math.floor(o.y) + o.h; y++) for (let x = Math.floor(o.x); x < Math.floor(o.x) + o.w; x++) {
          const t = o.dir === "h" ? (o.w <= 1 ? 0 : (x - Math.floor(o.x)) / (o.w - 1)) : (o.h <= 1 ? 0 : (y - Math.floor(o.y)) / (o.h - 1));
          set(x, y, [clamp(a[0] + (b[0] - a[0]) * t), clamp(a[1] + (b[1] - a[1]) * t), clamp(a[2] + (b[2] - a[2]) * t)]);
        }
        break;
      }
      case "noise": {
        const r = rng(o.seed ?? 1); const x0 = o.x ?? 0, y0 = o.y ?? 0, w = o.w ?? n, h = o.h ?? n;
        for (let y = y0; y < y0 + h; y++) for (let x = x0; x < x0 + w; x++) {
          const i = (y * n + x) * 4; const d = (r() - 0.5) * 2 * o.amount; // draw the number even on transparent pixels so the pattern doesn't depend on shape
          if (px[i + 3] > 0) { px[i] = clamp(px[i] + d); px[i + 1] = clamp(px[i + 1] + d); px[i + 2] = clamp(px[i + 2] + d); }
        }
        break;
      }
      case "shade": {
        // light from the top-left: lighten pixels whose up/left neighbour is empty, darken those whose down/right neighbour is empty
        const a = o.amount ?? 28; const src = px.slice();
        const has = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && src[(y * n + x) * 4 + 3] > 0;
        for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
          if (!has(x, y)) continue; const i = (y * n + x) * 4; let d = 0;
          if (!has(x, y - 1) || !has(x - 1, y)) d += a; if (!has(x, y + 1) || !has(x + 1, y)) d -= a;
          px[i] = clamp(px[i] + d); px[i + 1] = clamp(px[i + 1] + d); px[i + 2] = clamp(px[i + 2] + d);
        }
        break;
      }
      case "outline": {
        const c = P(o.c); const add: [number, number][] = [];
        for (let y = -1; y <= n; y++) for (let x = -1; x <= n; x++) {
          if (opaque(x, y)) continue;
          if (opaque(x + 1, y) || opaque(x - 1, y) || opaque(x, y + 1) || opaque(x, y - 1)) add.push([x, y]);
        }
        for (const [x, y] of add) set(x, y, c);
        break;
      }
    }
  };

  // mirror: ops draw the left half; copy it across after every op so later ops see a symmetric image
  const mirrorNow = () => { for (let y = 0; y < n; y++) for (let x = 0; x < n / 2; x++) { const a = (y * n + x) * 4, b = (y * n + (n - 1 - x)) * 4; if (px[a + 3]) { px[b] = px[a]; px[b + 1] = px[a + 1]; px[b + 2] = px[a + 2]; px[b + 3] = px[a + 3]; } } };
  for (const o of spec.ops) { draw(o); if (spec.mirror && o.op !== "outline") mirrorNow(); }
  return { size: n, px };
}
// A reference texture spec (a 9mm pistol) used by the tests and as the example shown to the model.
import type { TextureSpec } from "./dsl";

export const GLOCK: TextureSpec = {
  name: "glock_9mm",
  size: 32,
  palette: { k: "#101113", s: "#2c2f35", sh: "#555b64", f: "#1f2125", g: "#34373d", gh: "#50555e", m: "#9aa0a9", o: "#e8a63a" },
  ops: [
