// Cyrus engine core: the project + revision store and the identifier registry (DB half). SERVER ONLY.
// The only writer of CyrusProject / CyrusRevision / CyrusProjectAsset / CyrusIdentifier.
// Rules: revisions are append-only (no function here edits or deletes their content); a revision's status moves
// once, pending -> passed | failed; a project always records its last passing revision; a revert is a NEW revision
// that copies an older one's content. Appends lock the project row (FOR UPDATE), so seq has no gaps and two writers
// cannot both build on the same head.
import { randomBytes } from "node:crypto";
import { Prisma, type CyrusIdentifier, type CyrusProject, type CyrusRevision } from "@prisma/client";
import { db } from "../../db";
import { getAdapter } from "../adapters";
import { validateModSpec, GAME_ID_RE, type ModSpec, type SpecIssue } from "./spec";
import { diffManifests, validateEngineRecord, validateManifest, REVISION_KINDS, type EngineRecord, type ManifestDiff, type ManifestEntry, type RevisionKind, type RevisionStatus } from "./revisions";
import { buildIdentifier, glyphBlockStart, glyphHomeBlock, GLYPH_BLOCK, GLYPH_BLOCKS, namespaceFromSeed, type IdentifierKind } from "./identifiers";

export class EngineStoreError extends Error {
  constructor(public code: string, message: string, public issues: SpecIssue[] = []) {
    super(message);
    this.name = "EngineStoreError";
  }
}

const isUniqueViolation = (e: unknown, field?: string): boolean => {
  if (!(e instanceof Prisma.PrismaClientKnownRequestError) || e.code !== "P2002") return false;
  if (!field) return true;
  const t = (e.meta as { target?: unknown } | undefined)?.target;
  return (Array.isArray(t) ? t.join(",") : String(t ?? "")).includes(field);
};

// ---------------------------------------------------------------------------
// Projects
// ---------------------------------------------------------------------------

export type CreateProjectInput = { userId: string; game: string; title?: string | null; rootBuildId?: string | null };
export type CreateProjectOptions = {
  /** Test hook: the namespace to try on each attempt (default: namespaceFromSeed of the project id + attempt). */
  namespaceFor?: (projectId: string, attempt: number) => string;
  maxAttempts?: number;
};

/** Create a project and reserve its unique namespace. A namespace clash (another project holds it) retries with a new seed. */
export async function createProject(input: CreateProjectInput, opts: CreateProjectOptions = {}): Promise<CyrusProject> {
  if (!input.userId) throw new EngineStoreError("bad_input", "userId is required");
  if (!GAME_ID_RE.test(input.game) || !getAdapter(input.game)) throw new EngineStoreError("unknown_game", `no game adapter for "${input.game}"`);
  const id = "cp" + randomBytes(10).toString("hex");
  const nsFor = opts.namespaceFor ?? ((pid: string, n: number) => namespaceFromSeed(n === 0 ? pid : `${pid}:${n}`));
  const max = opts.maxAttempts ?? 8;
  for (let attempt = 0; attempt < max; attempt++) {
    const namespace = nsFor(id, attempt);
    try {
      return await db.cyrusProject.create({
        data: { id, userId: input.userId, game: input.game, namespace, title: input.title ?? null, rootBuildId: input.rootBuildId ?? null },
      });
    } catch (e) {
      if (isUniqueViolation(e, "namespace")) continue;
      if (isUniqueViolation(e, "rootBuildId")) throw new EngineStoreError("root_taken", "that build chain already has a project");
      throw e;
    }
  }
  throw new EngineStoreError("namespace_exhausted", `could not reserve a free namespace in ${max} attempts`);
}

export const getProject = (id: string) => db.cyrusProject.findUnique({ where: { id } });
export const projectForRootBuild = (rootBuildId: string) => db.cyrusProject.findUnique({ where: { rootBuildId } });

// ---------------------------------------------------------------------------
// Revisions
// ---------------------------------------------------------------------------

export type AddRevisionInput = {
  kind: Exclude<RevisionKind, "revert">;
  manifest: unknown;
  spec?: unknown;
  modBuildId?: string | null;
  engine?: EngineRecord | null;
  status?: RevisionStatus;
  message?: string | null;
  /** Optimistic check: the head this revision builds on (null = the project has no revisions yet). Omit to append to whatever the head is. */
  expectedHeadId?: string | null;
};

type InsertRow = {
  kind: RevisionKind; spec: ModSpec | null; manifest: ManifestEntry[]; modBuildId: string | null; engine: EngineRecord | null;
  status: RevisionStatus; message: string | null; revertOfId: string | null; expectedHeadId?: string | null;
};

const lockProject = async (tx: Prisma.TransactionClient, projectId: string) => {
  const rows = await tx.$queryRaw<{ id: string; namespace: string; game: string; headRevisionId: string | null; lastPassingRevisionId: string | null; revisionCount: number }[]>`
    SELECT "id", "namespace", "game", "headRevisionId", "lastPassingRevisionId", "revisionCount"
    FROM "CyrusProject" WHERE "id" = ${projectId} FOR UPDATE`;
  if (!rows.length) throw new EngineStoreError("not_found", "project not found");
  return rows[0];
};

/** Appends queue on the project row lock; give queued writers room before Prisma's 2 s default gives up. */
const TX = { maxWait: 10_000, timeout: 15_000 };

async function insertRevision(projectId: string, row: InsertRow): Promise<CyrusRevision> {
  return db.$transaction(async (tx) => {
    const p = await lockProject(tx, projectId);
    if (row.expectedHeadId !== undefined && row.expectedHeadId !== p.headRevisionId) {
      throw new EngineStoreError("stale_head", "the project moved on since this change was started; reload and try again");
    }
    if (row.spec && (row.spec.namespace !== p.namespace || row.spec.game !== p.game)) {
      throw new EngineStoreError("spec_mismatch", "the spec's game or namespace is not this project's");
    }
    const rev = await tx.cyrusRevision.create({
      data: {
        projectId, seq: p.revisionCount + 1, parentId: p.headRevisionId, kind: row.kind,
        spec: row.spec ? (row.spec as unknown as Prisma.InputJsonValue) : Prisma.DbNull,
        manifest: row.manifest as unknown as Prisma.InputJsonValue,
        modBuildId: row.modBuildId, engine: row.engine ? (row.engine as Prisma.InputJsonValue) : Prisma.DbNull,
        status: row.status, message: row.message, revertOfId: row.revertOfId,
      },
    });
    await tx.cyrusProject.update({
      where: { id: projectId },
      data: { headRevisionId: rev.id, revisionCount: rev.seq, ...(rev.status === "passed" ? { lastPassingRevisionId: rev.id } : {}) },
    });
    return rev;
  }, TX);
}

/** Append a revision on top of the project's head. Validates spec, manifest and engine record first. */
export async function addRevision(projectId: string, input: AddRevisionInput): Promise<CyrusRevision> {
  if (!(REVISION_KINDS as readonly string[]).includes(input.kind) || input.kind === ("revert" as string)) throw new EngineStoreError("bad_kind", `kind must be generated, edited, imported or asset (use revertTo for a revert)`);
  const status = input.status ?? "pending";
  if (!["pending", "passed", "failed"].includes(status)) throw new EngineStoreError("bad_status", "status must be pending, passed or failed");
  const m = validateManifest(input.manifest);
  if (!m.ok) throw new EngineStoreError("bad_manifest", "the file manifest is invalid", m.errors);
  const eng = validateEngineRecord(input.engine);
  if (!eng.ok) throw new EngineStoreError("bad_engine_record", "the engine record is invalid", eng.errors);
  let spec: ModSpec | null = null;
  if (input.spec !== undefined && input.spec !== null) {
    const v = validateModSpec(input.spec, { adapterFor: getAdapter });
    if (!v.ok) throw new EngineStoreError("bad_spec", "the mod spec is invalid", v.errors);
    spec = v.spec;
  }
  return insertRevision(projectId, {
    kind: input.kind, spec, manifest: m.entries, modBuildId: input.modBuildId ?? null, engine: input.engine ? eng.record : null,
    status, message: input.message ?? null, revertOfId: null, expectedHeadId: input.expectedHeadId,
  });
}

/** The one allowed change to a revision: pending -> passed | failed. A pass becomes the project's last passing revision if it is newer. */
export async function setRevisionStatus(revisionId: string, status: "passed" | "failed"): Promise<CyrusRevision> {
  if (status !== "passed" && status !== "failed") throw new EngineStoreError("bad_status", "status must be passed or failed");
  const rev = await db.cyrusRevision.findUnique({ where: { id: revisionId } });
  if (!rev) throw new EngineStoreError("not_found", "revision not found");
  return db.$transaction(async (tx) => {
    const p = await lockProject(tx, rev.projectId);
    const n = await tx.cyrusRevision.updateMany({ where: { id: revisionId, status: "pending" }, data: { status } });
    if (n.count !== 1) throw new EngineStoreError("not_pending", "only a pending revision can change status");
    if (status === "passed") {
      const current = p.lastPassingRevisionId ? await tx.cyrusRevision.findUnique({ where: { id: p.lastPassingRevisionId }, select: { seq: true } }) : null;
      if (!current || current.seq < rev.seq) await tx.cyrusProject.update({ where: { id: rev.projectId }, data: { lastPassingRevisionId: rev.id } });
    }
    return { ...rev, status };
  }, TX);
}

export async function getHead(projectId: string): Promise<CyrusRevision | null> {
  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { headRevisionId: true } });
  return p?.headRevisionId ? db.cyrusRevision.findUnique({ where: { id: p.headRevisionId } }) : null;
}

export async function lastPassing(projectId: string): Promise<CyrusRevision | null> {
  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { lastPassingRevisionId: true } });
  return p?.lastPassingRevisionId ? db.cyrusRevision.findUnique({ where: { id: p.lastPassingRevisionId } }) : null;
}

export const getRevision = (id: string) => db.cyrusRevision.findUnique({ where: { id } });
export const listRevisions = (projectId: string) => db.cyrusRevision.findMany({ where: { projectId }, orderBy: { seq: "asc" } });

export const manifestOf = (rev: Pick<CyrusRevision, "manifest">): ManifestEntry[] => (Array.isArray(rev.manifest) ? (rev.manifest as unknown as ManifestEntry[]) : []);

/** Files added / removed / changed going from revision `fromId` to `toId` (same project). */
export async function diffRevisions(fromId: string, toId: string): Promise<ManifestDiff> {
  const [a, b] = await Promise.all([getRevision(fromId), getRevision(toId)]);
  if (!a || !b) throw new EngineStoreError("not_found", "revision not found");
  if (a.projectId !== b.projectId) throw new EngineStoreError("bad_input", "revisions belong to different projects");
  return diffManifests(manifestOf(a), manifestOf(b));
}

/**
 * Revert = a NEW revision on top of the head that restores `targetId`'s spec, files and build link. History is kept.
 * The status carries over: the files are byte-identical (same manifest hashes), so the same checks apply.
 */
export async function revertTo(projectId: string, targetId: string, opts: { message?: string; expectedHeadId?: string | null } = {}): Promise<CyrusRevision> {
  const t = await getRevision(targetId);
  if (!t || t.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const engine = { ...((t.engine as EngineRecord | null) ?? {}), revertOf: t.id };
  return insertRevision(projectId, {
    kind: "revert", spec: (t.spec as unknown as ModSpec | null) ?? null, manifest: manifestOf(t), modBuildId: t.modBuildId, engine,
    status: t.status as RevisionStatus, message: opts.message ?? `Revert to revision ${t.seq}`, revertOfId: t.id, expectedHeadId: opts.expectedHeadId,
  });
}

// ---------------------------------------------------------------------------
// Assets (content-addressed; recording the same content twice returns the first row)
// ---------------------------------------------------------------------------

export type RecordAssetInput = {
  revisionId: string; assetKey: string; kind: "texture" | "sound" | "model" | "ui"; sha256: string; size: number;
  origin: "generated" | "library" | "upload" | "edited" | "imported"; mime?: string | null; path?: string | null; provenance?: Record<string, unknown> | null;
};

export async function recordAsset(projectId: string, a: RecordAssetInput) {
  if (!/^[0-9a-f]{64}$/.test(a.sha256)) throw new EngineStoreError("bad_input", "sha256 must be 64 lowercase hex characters");
  const rev = await getRevision(a.revisionId);
  if (!rev || rev.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const where = { projectId_kind_assetKey_sha256: { projectId, kind: a.kind, assetKey: a.assetKey, sha256: a.sha256 } };
  try {
    return await db.cyrusProjectAsset.create({
      data: { projectId, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ? (a.provenance as Prisma.InputJsonValue) : Prisma.DbNull },
    });
  } catch (e) {
    if (isUniqueViolation(e)) { const row = await db.cyrusProjectAsset.findUnique({ where }); if (row) return row; }
    throw e;
  }
}
export const listProjectAssets = (projectId: string) => db.cyrusProjectAsset.findMany({ where: { projectId }, orderBy: { createdAt: "asc" } });

// ---------------------------------------------------------------------------
// Identifier registry
// ---------------------------------------------------------------------------

/**
 * Reserve an identifier in the project's namespace. Idempotent: reserving the same (kind, key) again returns the
 * existing row. Glyphs get the first free codepoint from the namespace's home block (unique across all projects).
 */
export async function reserveIdentifier(projectId: string, kind: IdentifierKind, key: string): Promise<CyrusIdentifier> {
  const p = await getProject(projectId);
  if (!p) throw new EngineStoreError("not_found", "project not found");
  const built = buildIdentifier(p.namespace, kind, key);
  if (!built.ok) throw new EngineStoreError("bad_identifier", built.error);
  const where = { namespace_kind_key: { namespace: p.namespace, kind, key } };
  const existing = await db.cyrusIdentifier.findUnique({ where });
  if (existing) return existing;
  const base = { projectId, namespace: p.namespace, kind, key, fullId: built.id };
  if (kind !== "glyph") {
    try {
      return await db.cyrusIdentifier.create({ data: base });
    } catch (e) {
      if (isUniqueViolation(e)) { const row = await db.cyrusIdentifier.findUnique({ where }); if (row) return row; }
      throw e;
    }
  }
  const home = glyphHomeBlock(p.namespace);
  let tries = 0;
  for (let b = 0; b < GLYPH_BLOCKS && tries < 64; ) {
    const start = glyphBlockStart(home + b);
    const taken = new Set((await db.cyrusIdentifier.findMany({ where: { codepoint: { gte: start, lt: start + GLYPH_BLOCK } }, select: { codepoint: true } })).map((r) => r.codepoint));
    let cp = -1;
    for (let c = start; c < start + GLYPH_BLOCK; c++) if (!taken.has(c)) { cp = c; break; }
    if (cp < 0) { b++; continue; }
    tries++;
    try {
      return await db.cyrusIdentifier.create({ data: { ...base, codepoint: cp } });
    } catch (e) {
      if (isUniqueViolation(e, "codepoint")) continue; // another project took it: look again
      if (isUniqueViolation(e)) { const row = await db.cyrusIdentifier.findUnique({ where }); if (row) return row; }
      throw e;
    }
  }
  throw new EngineStoreError("glyphs_exhausted", "no free glyph codepoint");
}

export const listIdentifiers = (projectId: string) => db.cyrusIdentifier.findMany({ where: { projectId }, orderBy: [{ kind: "asc" }, { key: "asc" }] });
// Cyrus engine core: the pure half of the revision store (file manifests, diffs, engine records).
// A revision's file manifest lists every file of the mod project at that revision as { path, sha256, role }.
// Pure + client-safe; the DB half is lib/cyrus/engine-core/store.ts.
import type { SpecIssue } from "./spec";

export const REVISION_KINDS = ["generated", "edited", "imported", "asset", "revert"] as const;
export type RevisionKind = (typeof REVISION_KINDS)[number];
export const REVISION_STATUSES = ["pending", "passed", "failed"] as const;
export type RevisionStatus = (typeof REVISION_STATUSES)[number];

export const FILE_ROLES = ["source", "resource", "config", "asset", "resourcePack", "dataPack", "test", "doc", "artifact", "other"] as const;
export type FileRole = (typeof FILE_ROLES)[number];
export type ManifestEntry = { path: string; sha256: string; role: FileRole };
export const MAX_MANIFEST_FILES = 5000;

const SHA256 = /^[0-9a-f]{64}$/;

/** A safe project-relative path: forward slashes, no leading slash, no empty / "." / ".." segments, no control chars. */
export function isSafeProjectPath(p: unknown): p is string {
  if (typeof p !== "string" || p.length === 0 || p.length > 512) return false;
  if (p.startsWith("/") || p.includes("\\") || /[\u0000-\u001f]/.test(p)) return false;
  return p.split("/").every((s) => s.length > 0 && s !== "." && s !== "..");
}

export type ManifestResult = { ok: true; entries: ManifestEntry[] } | { ok: false; errors: SpecIssue[] };

/** Untrusted manifest -> entries sorted by path (a stable order, so equal manifests serialise identically). */
export function validateManifest(raw: unknown): ManifestResult {
  if (!Array.isArray(raw)) return { ok: false, errors: [{ path: "manifest", code: "not_array", message: "manifest must be an array" }] };
  if (raw.length > MAX_MANIFEST_FILES) return { ok: false, errors: [{ path: "manifest", code: "too_many_files", message: `at most ${MAX_MANIFEST_FILES} files` }] };
  const errors: SpecIssue[] = [];
  const seen = new Set<string>();
  const entries: ManifestEntry[] = [];
  raw.forEach((e, i) => {
    const at = `manifest[${i}]`;
    const r = (e ?? {}) as Record<string, unknown>;
    if (!isSafeProjectPath(r.path)) { errors.push({ path: `${at}.path`, code: "bad_path", message: "path must be a safe relative path" }); return; }
    if (typeof r.sha256 !== "string" || !SHA256.test(r.sha256)) errors.push({ path: `${at}.sha256`, code: "bad_sha256", message: "sha256 must be 64 lowercase hex characters" });
    if (!(FILE_ROLES as readonly string[]).includes(r.role as string)) errors.push({ path: `${at}.role`, code: "bad_role", message: `role must be one of ${FILE_ROLES.join(", ")}` });
    if (seen.has(r.path)) errors.push({ path: `${at}.path`, code: "duplicate_path", message: `${r.path} is listed twice` });
    seen.add(r.path);
    entries.push({ path: r.path, sha256: String(r.sha256), role: r.role as FileRole });
  });
  if (errors.length) return { ok: false, errors };
  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  return { ok: true, entries };
}

export type ManifestDiff = {
  added: ManifestEntry[];
  removed: ManifestEntry[];
  changed: { path: string; from: ManifestEntry; to: ManifestEntry }[];
  unchanged: number;
};

/** Files added, removed and changed (content or role) going from `from` to `to`. Pure. */
export function diffManifests(from: readonly ManifestEntry[], to: readonly ManifestEntry[]): ManifestDiff {
  const a = new Map(from.map((e) => [e.path, e]));
  const b = new Map(to.map((e) => [e.path, e]));
  const out: ManifestDiff = { added: [], removed: [], changed: [], unchanged: 0 };
  for (const [p, e] of b) {
    const old = a.get(p);
    if (!old) out.added.push(e);
    else if (old.sha256 !== e.sha256 || old.role !== e.role) out.changed.push({ path: p, from: old, to: e });
    else out.unchanged++;
  }
  for (const [p, e] of a) if (!b.has(p)) out.removed.push(e);
  const byPath = (x: { path: string }, y: { path: string }) => (x.path < y.path ? -1 : 1);
  out.added.sort(byPath); out.removed.sort(byPath); out.changed.sort(byPath);
  return out;
}

/**
 * What produced a revision, as far as it is known (MASTER-PLAN R0 "per-build engine-release record").
 * Every field optional: record what is known, never invent a value.
 */
export type EngineRecord = {
  promptVersion?: string;
  /** API sheets given to the model: name + content hash where known. */
  sheets?: { name: string; sha256?: string }[];
  rulesVersion?: string;
  scannerHash?: string;
  /** Build-service image digest (sha256:...) where known. */
  imageDigest?: string;
  model?: string;
  toolchain?: string;
  /** Set on a revert: the revision whose content this one restores. */
  revertOf?: string;
};
const ENGINE_KEYS = new Set(["promptVersion", "sheets", "rulesVersion", "scannerHash", "imageDigest", "model", "toolchain", "revertOf"]);

export function validateEngineRecord(raw: unknown): { ok: true; record: EngineRecord } | { ok: false; errors: SpecIssue[] } {
  if (raw === undefined || raw === null) return { ok: true, record: {} };
  if (typeof raw !== "object" || Array.isArray(raw)) return { ok: false, errors: [{ path: "engine", code: "not_object", message: "engine record must be an object" }] };
  const errors: SpecIssue[] = [];
  const r = raw as Record<string, unknown>;
  for (const k of Object.keys(r)) if (!ENGINE_KEYS.has(k)) errors.push({ path: `engine.${k}`, code: "unknown_field", message: `unknown engine record field ${k}` });
  for (const k of ["promptVersion", "rulesVersion", "scannerHash", "imageDigest", "model", "toolchain", "revertOf"]) {
    if (r[k] !== undefined && (typeof r[k] !== "string" || (r[k] as string).length > 200)) errors.push({ path: `engine.${k}`, code: "bad_value", message: `${k} must be a string (max 200)` });
  }
  if (r.sheets !== undefined) {
    const ok = Array.isArray(r.sheets) && r.sheets.length <= 50 && r.sheets.every((s) => s && typeof s === "object" && typeof (s as { name?: unknown }).name === "string" && ((s as { sha256?: unknown }).sha256 === undefined || SHA256.test(String((s as { sha256?: unknown }).sha256))));
    if (!ok) errors.push({ path: "engine.sheets", code: "bad_value", message: "sheets must be up to 50 { name, sha256? } entries" });
  }
  return errors.length ? { ok: false, errors } : { ok: true, record: r as EngineRecord };
}
// Cyrus engine core: reserved namespaces + the identifier registry rules (MASTER-PLAN 4.2).
// Every project reserves a namespace `nx_<hash>` when it is created (lib/cyrus/engine-core/store.ts), and every
// identifier a mod defines (item, model, sound, permission, command, recipe, glyph, config key) is built from it,
// so two Nxeon mods cannot collide by construction. Glyphs get codepoints from a per-namespace home block in the
// supplementary Private Use Areas. Pure, deterministic and client-safe (no crypto module, no DB).
// GAME-AGNOSTIC: the formats are generic `ns:key` / `ns.key` strings; an adapter maps them to a game's own syntax.

export const NAMESPACE_RE = /^nx_[a-z0-9]{8}$/;

export const IDENTIFIER_KINDS = ["item", "model", "sound", "permission", "command", "recipe", "glyph", "config"] as const;
export type IdentifierKind = (typeof IDENTIFIER_KINDS)[number];
export const isIdentifierKind = (v: unknown): v is IdentifierKind => typeof v === "string" && (IDENTIFIER_KINDS as readonly string[]).includes(v);

const SEG = "[a-z0-9_]+";
const KEY_RULES: Record<IdentifierKind, { re: RegExp; sep: ":" | "."; hint: string }> = {
  item: { re: /^[a-z0-9_]{1,48}$/, sep: ":", hint: "lowercase letters, digits, underscores" },
  recipe: { re: /^[a-z0-9_]{1,48}$/, sep: ":", hint: "lowercase letters, digits, underscores" },
  command: { re: /^[a-z0-9_]{1,32}$/, sep: ":", hint: "lowercase letters, digits, underscores (max 32)" },
  glyph: { re: /^[a-z0-9_]{1,48}$/, sep: ":", hint: "lowercase letters, digits, underscores" },
  model: { re: new RegExp(`^${SEG}(/${SEG}){0,3}$`), sep: ":", hint: "path segments of lowercase letters, digits, underscores joined by /" },
  sound: { re: new RegExp(`^${SEG}(\\.${SEG}){0,5}$`), sep: ":", hint: "segments of lowercase letters, digits, underscores joined by ." },
  permission: { re: /^[a-z0-9_-]+(\.[a-z0-9_-]+){0,5}$/, sep: ".", hint: "segments of lowercase letters, digits, - or _ joined by ." },
  config: { re: /^[a-z0-9_-]+(\.[a-z0-9_-]+){0,5}$/, sep: ".", hint: "segments of lowercase letters, digits, - or _ joined by ." },
};
const MAX_KEY = 64;

/** FNV-1a 64-bit (BigInt). Not a security hash: only spreads namespaces and glyph blocks evenly. */
export function fnv1a64(s: string): bigint {
  let h = 0xcbf29ce484222325n;
  const bytes = new TextEncoder().encode(s);
  for (const b of bytes) {
    h ^= BigInt(b);
    h = (h * 0x100000001b3n) & 0xffffffffffffffffn;
  }
  return h;
}

/** Deterministic namespace for a seed (the store seeds it with the project id, plus an attempt counter on a clash). */
export function namespaceFromSeed(seed: string): string {
  return "nx_" + fnv1a64(seed).toString(36).padStart(13, "0").slice(-8);
}
export const isNamespace = (v: unknown): v is string => typeof v === "string" && NAMESPACE_RE.test(v);

export type IdResult = { ok: true; id: string } | { ok: false; error: string };

export function buildIdentifier(namespace: string, kind: IdentifierKind, key: string): IdResult {
  if (!isNamespace(namespace)) return { ok: false, error: `"${namespace}" is not a reserved nx_ namespace` };
  const rule = KEY_RULES[kind];
  if (!rule) return { ok: false, error: `unknown identifier kind ${String(kind)}` };
  if (typeof key !== "string" || key.length === 0 || key.length > MAX_KEY || !rule.re.test(key)) return { ok: false, error: `${kind} key "${key}" must be ${rule.hint} (max ${MAX_KEY})` };
  return { ok: true, id: `${namespace}${rule.sep}${key}` };
}

export function parseIdentifier(kind: IdentifierKind, full: string): { namespace: string; key: string } | null {
  const rule = KEY_RULES[kind];
  if (!rule || typeof full !== "string") return null;
  const at = full.indexOf(rule.sep);
  if (at < 0) return null;
  const namespace = full.slice(0, at);
  const key = full.slice(at + 1);

