/// A typed mod project. Holds its reserved namespace and points at its head and
/// last passing revisions. The project, not the chat, is the source of truth.
model CyrusProject {
  id                    String   @id
  userId                String
  /// Game adapter id (lib/cyrus/adapters), e.g. "minecraft".
  game                  String
  /// Reserved at creation: nx_<8 chars>; every identifier of the mod lives under it.
  namespace             String   @unique
  title                 String?
  /// Optional link to a ModBuild chain (ModBuild.rootBuildId) this project grew from.
  rootBuildId           String?  @unique
  headRevisionId        String?
  lastPassingRevisionId String?
  revisionCount         Int      @default(0)
  createdAt             DateTime @default(now())
  updatedAt             DateTime @updatedAt

  @@index([userId, createdAt])
}

/// One immutable, append-only revision of a project. Content columns never change
/// after insert; `status` moves once from pending to passed or failed.
model CyrusRevision {
  id         String   @id @default(cuid())
  projectId  String
  /// 1, 2, 3 ... per project (no gaps; the project row is locked while appending).
  seq        Int
  parentId   String?
  /// generated | edited | imported | asset | revert
  kind       String
  /// ModSpec (lib/cyrus/engine-core/spec.ts), schemaVersion inside.
  spec       Json?
  /// [{ path, sha256, role }] sorted by path (lib/cyrus/engine-core/revisions.ts).
  manifest   Json
  /// The ModBuild that produced (or verified) this revision, when there is one.
  modBuildId String?
  /// What built it: prompt version, sheets, rules, scanner hash, image digest (where known).
  engine     Json?
  /// pending | passed | failed
  status     String   @default("pending")
  message    String?
  /// Set on kind=revert: the revision whose content this one restores.
  revertOfId String?
  createdAt  DateTime @default(now())

  @@unique([projectId, seq])
  @@index([projectId, createdAt])
  @@index([modBuildId])
}

/// A content-addressed asset (texture, sound, model, ui) that a project holds.
/// Never gated to keep, install or export (lib/cyrus/engine-core/asset-gate.ts).
model CyrusProjectAsset {
  id         String   @id @default(cuid())
  projectId  String
  /// The spec asset slot id.
  assetKey   String
  /// texture | sound | model | ui
  kind       String
  sha256     String
  size       Int
  mime       String?
  /// Storage path of the bytes, when stored.
  path       String?
  /// generated | library | upload | edited | imported
  origin     String
  /// Generator / library item / licence, as known.
  provenance Json?
  /// The revision that introduced this content.
  revisionId String
  createdAt  DateTime @default(now())

  @@unique([projectId, kind, assetKey, sha256])
  @@index([projectId])
}

/// The identifier registry: one row per identifier a project defines.
/// Unique per (namespace, kind, key); glyph codepoints are unique across ALL
/// projects, so Mod Packs can never collide on a glyph.
model CyrusIdentifier {
  id        String   @id @default(cuid())
  projectId String
  namespace String
  /// item | model | sound | permission | command | recipe | glyph | config
  kind      String
  key       String
  /// The full namespaced identifier (lib/cyrus/engine-core/identifiers.ts buildIdentifier).
  fullId    String
  codepoint Int?     @unique
  createdAt DateTime @default(now())

  @@unique([namespace, kind, key])
  @@index([projectId])
}

