// Server-only HTTP client for the Mod Builder build service (build VM).
//
// Config, first hit wins:
//   env MODBUILDER_URL / MODBUILDER_API_KEY
//   file $MODBUILDER_ENV_FILE (default /etc/nxeon/modbuilder.env, root:nxeon 0640 so the web user can read it), KEY=VALUE lines
// The URL is the primary-side end of the SSH tunnel
// (nxeon-modbuilder-tunnel.service: 127.0.0.1:7340 -> VM 127.0.0.1:7340).
import { readFileSync } from "node:fs";

type Cfg = { url: string; key: string };
let cached: { cfg: Cfg | null; at: number } | null = null;

export function modBuilderConfig(): Cfg | null {
  if (cached && Date.now() - cached.at < 60_000) return cached.cfg;
  let url = process.env.MODBUILDER_URL || "";
  let key = process.env.MODBUILDER_API_KEY || "";
  if (!url || !key) {
    try {
      const text = readFileSync(process.env.MODBUILDER_ENV_FILE || "/etc/nxeon/modbuilder.env", "utf8");
      for (const line of text.split("\n")) {
        const m = line.match(/^\s*([A-Z_]+)\s*=\s*(.*)\s*$/);
        if (!m) continue;
        if (m[1] === "MODBUILDER_URL" && !url) url = m[2];
        if (m[1] === "MODBUILDER_API_KEY" && !key) key = m[2];
      }
    } catch { /* not configured */ }
  }
  const cfg = url && key ? { url: url.replace(/\/+$/, ""), key } : null;
  cached = { cfg, at: Date.now() };
  return cfg;
}

export class ModBuilderUnavailable extends Error {}

async function call(path: string, init: RequestInit & { timeoutMs?: number } = {}): Promise<Response> {
  const cfg = modBuilderConfig();
  if (!cfg) throw new ModBuilderUnavailable("Mod Builder service is not configured");
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), init.timeoutMs ?? 15_000);
  try {
    return await fetch(cfg.url + path, {
      ...init,
      cache: "no-store",
      signal: ctl.signal,
      headers: { ...(init.headers || {}), Authorization: `Bearer ${cfg.key}`, ...(init.body ? { "Content-Type": "application/json" } : {}) },
    });
  } catch (e) {
    throw new ModBuilderUnavailable(`Mod Builder service unreachable: ${(e as Error).message}`);
  } finally {
    clearTimeout(t);
  }
}

/** Raw service record (see services/modbuilder/server.js). Only the fields the portal reads. */
export type ServiceBuild = {
  id: string; status: string; error: string | null; errorCode: string | null; errorDetail?: string | null;
  attempts: number; repairs: number; costUsd: number; durationMs: number; pluginName: string | null; version?: string;
  jar: { name: string; size: number; sha256: string } | null;
  summary: { tagline: string; text: string; howToUse: string[]; limitations: string[]; changes: string } | null;
  commands: unknown[]; permissions: unknown[]; config: unknown[]; warnings: string[]; files: { path: string; size: number }[];
  safety: { verdict: "pass" | "warn" | "block"; findings: unknown[] } | null;
  /** Normalized nx-capabilities manifest (service 0.6+, only when the build declares networking). */
  capabilities?: unknown;
  events: { at: string; stage: string; message: string; detail?: string }[];
  queuePosition: number; finishedAt: string | null;
  route?: { class: string; method: string; score: number } | null;
  aiCalls?: { kind?: string; route?: string | null; model: string; resolvedModel?: string | null; costUsd: number; turns?: number | null; durationMs?: number | null }[];
};

export async function svcHealth(): Promise<{ ok: boolean; [k: string]: unknown } | null> {
  try {
    const r = await call("/health", { timeoutMs: 4000 });
    return r.ok ? await r.json() : null;
  } catch { return null; }
}

/**
 * `tier` (Cyrus model picker, lib/cyrus/models.ts): optional explicit model override.
 * Service image modbuilder:0.3+ maps katara/saka/yakko to a model and answers 400 for
 * anything else; omitted = the service's own routing (backwards compatible).
 */
export type SvcImage = { name: string; type: string; data: string };

/**
 * `images` (Cyrus, service image modbuilder:0.4+): reference images as base64. The service
 * re-checks type and size and puts them in the build workspace for the model to Read.
 * Omitted = no images (older images answer 400 for unknown shapes, so only send when present).
 */
export async function svcCreate(body: { id: string; prompt: string; mcVersion: string; pluginName?: string; baseBuildId?: string; changeRequest?: string; tier?: "katara" | "saka" | "yakko"; images?: SvcImage[] }): Promise<ServiceBuild> {
  const r = await call("/builds", { method: "POST", body: JSON.stringify(body), timeoutMs: body.images?.length ? 45_000 : 15_000 });
  const j = await r.json().catch(() => ({}));
  if (r.status !== 202) throw new Error((j as { error?: string }).error || `service returned ${r.status}`);
  return j as ServiceBuild;
}

export async function svcGet(id: string): Promise<ServiceBuild | null> {
  const r = await call(`/builds/${encodeURIComponent(id)}`);
  if (r.status === 404) return null;
  if (!r.ok) throw new ModBuilderUnavailable(`service returned ${r.status}`);
  return (await r.json()) as ServiceBuild;
}

export async function svcCancel(id: string): Promise<void> {
  await call(`/builds/${encodeURIComponent(id)}/cancel`, { method: "POST" });
}

export async function svcArtifact(id: string): Promise<Buffer> {
  const r = await call(`/builds/${encodeURIComponent(id)}/artifact`, { timeoutMs: 60_000 });
  if (!r.ok) throw new Error(`artifact fetch failed (${r.status})`);
  return Buffer.from(await r.arrayBuffer());
}

export async function svcSource(id: string, path: string): Promise<Response> {
  return call(`/builds/${encodeURIComponent(id)}/source?path=${encodeURIComponent(path)}`);
}

/** Live view of a running build (service 0.4+): src/main/** files + the file being written right now. */
export type SvcLive = {
  live: boolean;
  status: string;
  files: { path: string; size: number; hash: string }[];
  draft: { path: string; op: "write" | "edit"; seq: number; from: number; text: string; total: number; done: boolean } | null;
};

export async function svcLive(id: string, draft?: string, from?: number, seq?: number): Promise<SvcLive | null> {
  const q = draft ? `?draft=${encodeURIComponent(draft)}&seq=${Math.max(0, Math.floor(seq ?? 0))}&from=${Math.max(0, Math.floor(from ?? 0))}` : "";
  const r = await call(`/builds/${encodeURIComponent(id)}/live${q}`, { timeoutMs: 8000 });
  // An older service image has no /live: treat as "nothing live" rather than an error.
  if (r.status === 404) return null;
  if (!r.ok) throw new ModBuilderUnavailable(`service returned ${r.status}`);
  return (await r.json()) as SvcLive;
}

export async function svcSourceZip(id: string): Promise<Response> {
  return call(`/builds/${encodeURIComponent(id)}/source.zip`, { timeoutMs: 60_000 });
}
// ModBuild persistence: mirror the build service's status into the DB row and
// keep the finished jar on the primary. Used by the API routes (sync on read,
// while someone watches) and by the worker sweep (so a build finishes even if
// nobody keeps the page open). Plain module: safe in the worker.
import { createHash } from "node:crypto";
import { mkdir, writeFile, rename, readFile } from "node:fs/promises";
import { join } from "node:path";
import type { ModBuild, Prisma } from "@prisma/client";
import { db } from "../db";
import { svcArtifact, svcGet, type ServiceBuild } from "./client";
import { isTerminal, type ModBuildResult, type ModBuildView } from "./types";
import { readCyrusMeta } from "../cyrus/meta";
import { safeSettle } from "../cyrus/tokens/builds";
import { onBuildSettled } from "../cyrus-mods/pages";

export const MODBUILD_DIR = process.env.NXEON_MODBUILD_DIR || "/var/lib/nxeon/modbuilds";
export const jarPathFor = (id: string) => join(MODBUILD_DIR, `${id}.jar`);

// A build the service never heard back on for this long is failed (the VM was
// rebuilt, the tunnel down for an hour, ...). Generous: real builds take 1-10 min.
const STALE_MS = 2 * 60 * 60 * 1000;

function toResult(s: ServiceBuild): ModBuildResult {
  return {
    summary: s.summary,
    commands: (s.commands || []) as ModBuildResult["commands"],
    permissions: (s.permissions || []) as ModBuildResult["permissions"],
    config: (s.config || []) as ModBuildResult["config"],
    warnings: s.warnings || [],
    files: s.files || [],
    safety: (s.safety as ModBuildResult["safety"]) || null,
    ...(s.capabilities ? { capabilities: s.capabilities } : {}),
    events: (s.events || []).slice(-150),
    repairs: s.repairs || 0,
    queuePosition: s.queuePosition || 0,
    errorDetail: s.errorDetail ? String(s.errorDetail).slice(0, 6000) : null,
    ai: {
      route: s.route?.class ?? null,
      routeMethod: s.route?.method ?? null,
      routeScore: s.route?.score ?? null,
      calls: (s.aiCalls || []).slice(0, 20).map((c) => ({
        kind: c.kind || "generate", route: c.route ?? null, model: c.model, resolvedModel: c.resolvedModel ?? null,
        costUsd: c.costUsd || 0, turns: c.turns ?? null, durationMs: c.durationMs ?? null,
      })),
    },
  };
}

/** Pull the service's view of one build into its row. Never throws for an unreachable service. */
export async function syncBuild(row: ModBuild): Promise<ModBuild> {
  const out = await syncBuildRow(row);
  // Cyrus tokens: a build that just finished settles its hold (idempotent, never throws).
  if (isTerminal(out.status) && !isTerminal(row.status)) await safeSettle(out);
  return out;
}

async function syncBuildRow(row: ModBuild): Promise<ModBuild> {
  if (isTerminal(row.status)) return row;
  let s: ServiceBuild | null;
  try {
    s = await svcGet(row.id);
  } catch {
    if (Date.now() - row.createdAt.getTime() > STALE_MS) {
      return db.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "unreachable", error: "We lost contact with the builder while this was running. Please try again.", finishedAt: new Date() } });
    }
    return row;
  }
  if (!s) {
    return db.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "lost", error: "The builder has no record of this build. Please try again.", finishedAt: new Date() } });
  }
  const data: Prisma.ModBuildUpdateInput = {
    status: s.status,
    attempts: s.attempts || 0,
    costUsd: s.costUsd || 0,
    durationMs: s.durationMs || null,
    pluginName: s.pluginName || row.pluginName,
    version: s.version || row.version,
    error: s.error,
    errorCode: s.errorCode,
    result: toResult(s) as unknown as Prisma.InputJsonValue,
  };
  if (s.status === "succeeded" && s.jar) {
    // Store the jar before flipping the row to succeeded, so "succeeded" always
    // means "downloadable".
    const bytes = await svcArtifact(row.id);
    const sha = createHash("sha256").update(bytes).digest("hex");
    if (sha !== s.jar.sha256) throw new Error("artifact checksum mismatch");
    await mkdir(MODBUILD_DIR, { recursive: true, mode: 0o750 });
    const dest = jarPathFor(row.id);
    await writeFile(dest + ".part", bytes, { mode: 0o640 });
    await rename(dest + ".part", dest);
    Object.assign(data, { jarName: s.jar.name, jarSize: bytes.length, jarSha256: sha, jarPath: dest });
  }
  if (isTerminal(s.status)) data.finishedAt = s.finishedAt ? new Date(s.finishedAt) : new Date();
  const updated = await db.modBuild.update({ where: { id: row.id }, data });
  // Cyrus mods: the first finished version creates the mod's NxLabs page (private
  // by default); every later version regenerates it. Never fails the build.
  if (updated.status === "succeeded") await onBuildSettled(updated).catch(() => {});
  return updated;
}

export async function readJar(row: ModBuild): Promise<Buffer> {
  if (!row.jarPath || row.status !== "succeeded") throw new Error("no jar");
  return readFile(row.jarPath);
}

/** Worker sweep: advance every in-flight build. */
export async function sweepModBuilds(): Promise<void> {
  const rows = await db.modBuild.findMany({ where: { status: { notIn: ["succeeded", "failed"] } }, take: 20, orderBy: { createdAt: "asc" } });
  for (const r of rows) {
    try { await syncBuild(r); } catch (e) { console.error("[modbuilder] sync failed", r.id, (e as Error).message); }
  }
}

/** The customer never sees which models ran or what they cost. */
function publicResult(r: ModBuildResult | null): ModBuildResult | null {
  if (!r) return null;
  const { ai, ...rest } = r;
  void ai;
  return rest;
}

export function toView(row: ModBuild): ModBuildView {
  return {
    id: row.id,
    status: row.status as ModBuildView["status"],
    prompt: row.prompt,
    changeRequest: row.changeRequest,
    baseBuildId: row.baseBuildId,
    rootBuildId: row.rootBuildId,
    mcVersion: row.mcVersion,
    pluginName: row.pluginName,
    version: row.version,
    error: row.error,
    errorCode: row.errorCode,
    attempts: row.attempts,
    durationMs: row.durationMs,
    jarName: row.jarName,
    jarSize: row.jarSize,
    createdAt: row.createdAt.toISOString(),
    finishedAt: row.finishedAt ? row.finishedAt.toISOString() : null,
    result: publicResult(row.result as unknown as ModBuildResult | null),
    lastInstall: (row.lastInstall as unknown as ModBuildView["lastInstall"]) ?? null,
    cyrus: row.cyrus ? readCyrusMeta(row.cyrus) : null,
  };
}
