      "Read(**/.credentials.json)", "Read(**/.claude/**)", "Read(**/.env*)", "Edit(**/.credentials.json)", "Write(**/.credentials.json)", "Grep(**/.credentials.json)", "Glob(**/.credentials.json)",
    ],
