// A gateway that namespaces its models ("cc/claude-sonnet-5-5") needs MB_MODEL_PREFIX="cc/" in /root/claudebox.env.
const MODEL_PREFIX = process.env.MB_MODEL_PREFIX || "";
const cliModel = (m) => (MODEL_PREFIX && m && !String(m).startsWith(MODEL_PREFIX) ? MODEL_PREFIX + m : m);
function effortFor(model) { return EFFORT && !/haiku/i.test(String(model)) ? EFFORT : null; }

async function callClaude(rec, ctl, ws, prompt, { resume, model, kind }) {
  // The tool set is fixed per build (tools are the first part of the cached prompt prefix).
  const tools = Array.isArray(rec.toolset) && rec.toolset.length ? rec.toolset : FULL_TOOLS;
  const isRepair = /^repair/.test(String(kind || ""));
  const args = ["-p", "--output-format", "stream-json", "--verbose",
    "--permission-mode", "acceptEdits",
    "--tools", ...tools,
    "--settings", SETTINGS, "--strict-mcp-config",
    "--include-partial-messages",
    "--model", cliModel(model), "--max-turns", String(isRepair ? Math.min(MAX_TURNS, MAX_TURNS_REPAIR) : MAX_TURNS),
    "--max-budget-usd", String(Math.max(0.2, Math.min(CALL_BUDGET_USD, BUILD_BUDGET_USD - rec.costUsd))),
    "--system-prompt", P.systemPrompt(rec.mcVersion)];
  const effort = effortFor(model);
  if (effort) args.push("--effort", effort);
  if (resume) args.push("--resume", resume); else args.push("--session-id", rec.sessionId);
  args.push("--", prompt);

  let buf = "", result = null, wroteAny = false, callModel = null;
  const meter = U.newMeter();
  const onStdout = (d) => {
    buf += d;
    let i;
    while ((i = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, i); buf = buf.slice(i + 1);
      if (!line.trim()) continue;
      let msg; try { msg = JSON.parse(line); } catch { continue; }
      U.onMessage(meter, msg);
      if (msg.type === "stream_event" && msg.event) {
        // Live code: follow the Write/Edit tool input as the model generates it.
        const ev = msg.event;
        if (ev.type === "content_block_start" && ev.content_block && ev.content_block.type === "tool_use") {
          const name = ev.content_block.name;
          ctl.draft = (name === "Write" || name === "Edit" || name === "MultiEdit") ? { tool: name, json: "", idx: ev.index, at: Date.now(), seq: (ctl.draft ? ctl.draft.seq : 0) + 1 } : null;
        } else if (ev.type === "content_block_delta" && ev.delta && ev.delta.type === "input_json_delta" && ctl.draft && ctl.draft.idx === ev.index) {
          if (ctl.draft.json.length < 1.5 * 1024 * 1024) ctl.draft.json += ev.delta.partial_json || "";
          ctl.draft.at = Date.now();
        } else if (ev.type === "content_block_stop" && ctl.draft && ctl.draft.idx === ev.index) {
          ctl.draft.done = true;
        }
        continue;
      }
      if (msg.type === "assistant" && msg.message && Array.isArray(msg.message.content)) {
        for (const c of msg.message.content) {
          if (c.type !== "tool_use") continue;
          const fp = c.input && (c.input.file_path || c.input.path || "");
          const rel = fp ? path.relative(ws, fp) || fp : "";
          const short = rel.split("/").pop();
          if (c.name === "Write" || c.name === "Edit" || c.name === "MultiEdit") {
            if (!wroteAny && rec.status === "planning") setStage(rec, "coding", "Writing the plugin code");
            wroteAny = true;
            event(rec, rec.status, `${c.name === "Write" ? "Wrote" : "Edited"} ${short}`);
          } else if (c.name === "Read" && short) event(rec, rec.status, `Reading ${short}`);
        }
      } else if (msg.type === "user" && msg.message && Array.isArray(msg.message.content)) {
        // Rejected tool calls (e.g. a Write outside the workspace): internal diagnostics only.
        for (const c of msg.message.content) {
          if (c.type === "tool_result" && c.is_error) {
            const t = Array.isArray(c.content) ? c.content.map((x) => x.text || "").join(" ") : String(c.content || "");
            rec.toolErrors = [...(rec.toolErrors || []), t.slice(0, 200)].slice(-20);
          }
        }
      } else if (msg.type === "system" && msg.subtype === "init" && msg.model) {
        callModel = msg.model;
        if (!rec.resolvedModel) rec.resolvedModel = msg.model;
      } else if (msg.type === "result") result = msg;
    }
  };
  const r = await run("claude", args, { cwd: ws, env: childEnv(true), timeout: CALL_TIMEOUT_MS, onStdout, track: ctl });
  ctl.child = null;
  const cost = result && typeof result.total_cost_usd === "number" ? result.total_cost_usd : 0;
  rec.costUsd = +(rec.costUsd + cost).toFixed(4);
  const mu = U.summarize(meter);
  const call = { at: now(), kind: kind || (resume ? "repair" : "generate"), route: rec.route ? rec.route.class : null, model, resolvedModel: callModel, costUsd: cost, tokens: mu.tokens, turns: result ? result.num_turns : null, durationMs: result ? result.duration_ms : null, subtype: result ? result.subtype : null, exit: r.code,
    apiMs: mu.apiMs, toolCalls: mu.toolCalls, turnsDetail: mu.turnsDetail, explore: mu.explore, effort, tools: tools.length };
  const callTokens = mu.tokens;
  rec.aiCalls.push(call);
  U.addCall(rec, call);
  rec.tokens.input += callTokens.input;
  rec.tokens.output += callTokens.output;
  save(rec);
  if (ctl.cancelled) throw fail("cancelled", "Build cancelled.");
  if (!result) {
    log("error", "claude produced no result", { id: rec.id, code: r.code, err: r.err.slice(-2000) });
    const authish = /auth|401|403|login|credit|quota|rate.?limit|overloaded/i.test(r.err);
    throw fail(r.timedOut ? "timeout" : "ai_unavailable", r.timedOut ? "The AI took too long on this one. Try a smaller request." : "The AI builder is unavailable right now. Please try again in a few minutes.", authish ? "AI service error" : r.err.slice(-1500));
  }
  if (result.subtype === "error_max_budget_usd") throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request or split it into two plugins.");
  // The model provider's own safeguard blocked the request (seen with Sonnet 5.5 on
  // the backdoor / env-dump eval prompts): that is a refusal, not an outage.
  if (result.is_error && /safeguards flagged|\[cyber\]|usage polic/i.test(String(result.result || ""))) {
    throw fail("refused", "We can't build this one. It goes against our plugin safety rules.", String(result.result).slice(0, 300));
  }
  if (result.is_error && result.subtype !== "error_max_turns") {
    throw fail("ai_unavailable", "The AI builder hit an error. Please try again in a few minutes.", String(result.result || result.subtype).slice(0, 1500));
  }
  return result;
}

// One very cheap Haiku call (no tools, one turn). `kind` names it in the usage record.
async function haikuAsk(rec, ctl, system, text, kind) {
  const args = ["-p", "--output-format", "json", "--tools", "", "--strict-mcp-config", "--settings", SETTINGS,
    "--model", cliModel(R.HAIKU), "--max-turns", "1", "--max-budget-usd", "0.05", "--system-prompt", system, "--", `<request>\n${text}\n</request>`];
  const cwd = path.join(WORK, `${rec.id}-${kind}`);
  fs.mkdirSync(cwd, { recursive: true });
  // One-line answers: no extended thinking (a measured guard call spent 1,358 output tokens and 14 s thinking before a one-word verdict).
  const env = childEnv(true); env.MAX_THINKING_TOKENS = "0";
  const r = await run("claude", args, { cwd, env, timeout: 60000, track: ctl });
  ctl.child = null;
  rmrf(cwd);
  let j = null; try { j = JSON.parse(r.out); } catch { /* fall through */ }
  const cost = j && typeof j.total_cost_usd === "number" ? j.total_cost_usd : 0;
  rec.costUsd = +(rec.costUsd + cost).toFixed(4);
  const ju = (j && j.usage) || {};
  const call = { at: now(), kind, route: null, model: R.HAIKU, resolvedModel: R.HAIKU, costUsd: cost, turns: j ? j.num_turns : null, durationMs: j ? j.duration_ms : null, subtype: j ? j.subtype : null, exit: r.code,
    tokens: { input: (ju.input_tokens || 0) + (ju.cache_creation_input_tokens || 0) + (ju.cache_read_input_tokens || 0), cacheRead: ju.cache_read_input_tokens || 0, output: ju.output_tokens || 0, uncached: ju.input_tokens || 0 } };
  rec.aiCalls.push(call);
  U.addCall(rec, call);
  return j && typeof j.result === "string" ? j.result : null;
}

// Answers simple|standard|complex (MB_CLASSIFIER=haiku).
async function classifyWithHaiku(rec, ctl, text) {
  const out = await haikuAsk(rec, ctl, R.CLASSIFIER_PROMPT, text, "classify");
  return out ? (out.toLowerCase().match(/simple|standard|complex/) || [null])[0] : null;
}

// The intake guard (MB_GUARD): one Haiku call over the customer's text BEFORE the main model sees it. It also rates the
// difficulty, so it replaces the separate classifier call when both would run. A refusal costs a fraction of a cent and
// never reaches the main model. It is a filter, not the boundary: the main model has no shell or network, only
// workspace-scoped file tools, and everything it writes is compiled and bytecode-scanned afterwards.
async function guardRequest(rec, ctl) {
  if (R.CFG.guard === "off") return;
  const text = rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt;
  let verdict = null;
  try { verdict = R.parseGuard(await haikuAsk(rec, ctl, R.GUARD_PROMPT, text, "guard")); } catch { verdict = null; }
  if (!verdict) {
    event(rec, rec.status, "Intake check unavailable, continuing");
    rec.guard = { verdict: "error" };
    if (R.CFG.guard === "strict") throw fail("unavailable", "We couldn't check this request right now. Please try again in a minute.");
    return;
  }
  rec.guard = verdict;
  if (verdict.verdict === "refuse") {
    throw fail("refused", "We can't build this one. It doesn't read like a Minecraft plugin request, or it goes against our plugin safety rules.", `guard:${verdict.code}`);
  }
  if (verdict.class) rec.guardClass = verdict.class;
}

async function chooseRoute(rec, ctl) {
  if (rec.override) {
    // Customer picked the model (tier). No classifier call; repairs stay on it.
    const h = R.classifyHeuristic(rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt);
    const m = rec.override.model;
    const up = rec.override.tier ? R.TIERS[R.TIER_UP[rec.override.tier]] : m;
    return { ...h, heuristicClass: h.class, class: rec.override.tier || "override", method: "override", tier: rec.override.tier, models: { generate: m, repairCheap: null, escalate: up, escalateAfter: 2 } };
  }
  const base = rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt;
  const h = R.classifyHeuristic(rec.prompt);
  let route = { ...h };
  if (rec.baseBuildId) {
    // A change request on an existing plugin: at least as hard as the change itself,
    // and the model must read the old code, so never below the original's class.
    const hc = R.classifyHeuristic(rec.changeRequest);
    route = { ...h, class: R.maxClass(h.class, hc.class), changeScore: hc.score };
  }
  const sameModel = new Set(Object.values(R.CFG.models)).size === 1;
  if (rec.guardClass && R.CFG.classifier === "haiku" && R.CFG.routing && !sameModel) route = { ...route, heuristicClass: route.class, class: rec.guardClass, method: "haiku (intake guard)" };
  else if (R.CFG.classifier === "haiku" && sameModel && R.CFG.routing) route = { ...route, method: "heuristic (all classes use one model, classifier skipped)" };
  else if (R.CFG.classifier === "haiku") {
    const word = await classifyWithHaiku(rec, ctl, base).catch(() => null);
    route = { ...route, heuristicClass: route.class, class: word || route.class, method: word ? "haiku" : "heuristic (haiku failed)" };
  }
  if (!R.CFG.routing) route = { ...route, routedClass: route.class, method: `${route.method}, routing off` };
  const gen = R.CFG.routing ? R.CFG.models[route.class] : MODEL;
  route.models = { generate: gen, repairCheap: R.CFG.routing && R.CFG.repairCheapFirst ? R.CFG.repairCheapModel : null, escalate: R.CFG.routing ? escalateFrom(gen) : REPAIR_MODEL };
  return route;
}
// The model a failed repair escalates to: one class up from the generation model.
function escalateFrom(model) {
  const m = R.CFG.models;
  if (model === m.simple) return m.standard;
  if (model === m.standard) return m.complex;
  return model;
}

function fail(code, message, detail) { const e = new Error(message); e.code = code; e.detail = detail; return e; }

