const unzip = (z: Buffer) => {
  const eocd = z.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
  const n = z.readUInt16LE(eocd + 10); let p = z.readUInt32LE(eocd + 16); const out = new Map<string, Buffer>();
  for (let i = 0; i < n; i++) {
    const crc = z.readUInt32LE(p + 16), csz = z.readUInt32LE(p + 20), usz = z.readUInt32LE(p + 24), nl = z.readUInt16LE(p + 28), el = z.readUInt16LE(p + 30), cl = z.readUInt16LE(p + 32), off = z.readUInt32LE(p + 42);
    const name = z.subarray(p + 46, p + 46 + nl).toString("utf8");
    const lnl = z.readUInt16LE(off + 26), lel = z.readUInt16LE(off + 28);
    const data = inflateRawSync(z.subarray(off + 30 + lnl + lel, off + 30 + lnl + lel + csz));
    assert.equal(data.length, usz); assert.equal(crc32(data), crc);
    out.set(name, data); p += 46 + nl + el + cl;
  }
  return out;
};

