  const rows = await tx.$queryRaw<RowRec[]>`SELECT "id","status","version","sha256","family","dependents","refCount" FROM "CyrusServerManagedPlugin" WHERE "serverId" = ${serverId} AND "key" = ${key} FOR UPDATE`;
  if (!rows[0]) throw new Error("managed plugin row vanished");
  return rows[0];
}

