// Cyrus mod pages: the PURE half (client-safe, unit-tested).
//
// A Cyrus mod is one ModBuild version chain (every version shares rootBuildId).
// Its NxLabs page is GENERATED from the chain's succeeded builds: nothing on it
// is hand-written or guessed. buildModDoc() turns the builds into the page body
// stored in CyrusModPage.doc; the server half (./pages.ts) calls it whenever a
// version finishes.
import type { MbCommand, MbConfig, MbPermission, ModBuildResult } from "../modbuilder/types";

/** Minimal ModBuild shape the generator reads (a Prisma ModBuild satisfies it). */
export type ChainBuild = {
  id: string;
  status: string;
  prompt: string;
  changeRequest: string | null;
  baseBuildId: string | null;
  rootBuildId: string | null;
  mcVersion: string;
  pluginName: string | null;
  version: string | null;
  jarName: string | null;
  jarSize: number | null;
  jarSha256?: string | null;
  result: unknown;
  cyrus?: unknown;
  createdAt: Date;
  finishedAt: Date | null;
};

export type CyrusDocVersion = {
  buildId: string;
  /** 1-based position among the chain's succeeded versions, oldest first. */
  n: number;
  version: string | null;
  mcVersion: string;
  at: string;
  /** Release notes: the builder's own "what changed" summary, else the change request, else "First version". */
  notes: string;
  /** What the creator asked for (the change request; the original prompt for v1). */
  request: string;
  basedOn: string | null;
  jarName: string | null;
  jarSize: number | null;
  jarSha256: string | null;
  safety: "pass" | "warn" | "block" | null;
};

export type CyrusModDoc = {
  v: 1;
  name: string;
  pluginName: string | null;
  tagline: string | null;
  summary: string | null;
  howToUse: string[];
  limitations: string[];
  commands: MbCommand[];
  permissions: MbPermission[];
  config: MbConfig[];
  /** Server software + Minecraft versions the published builds target (newest first). */
  compat: { software: string[]; mcVersions: string[]; note: string };
  /** Newest first. */
  versions: CyrusDocVersion[];
  /** The version the page presents as current (the creator's restored head, else the newest). */
  currentBuildId: string | null;
  /** Source files of the current version (src/** only, no build output). */
  files: { path: string; size: number }[];
  generatedAt: string;
};

/** What a Cyrus plugin runs on: generated plugins target the Paper API (lib/modbuilder/install.ts MB_INSTALL_VARIANTS). */
  const cur = currentVersion(chain);
  return t || cur?.pluginName || root?.pluginName || "Untitled Cyrus mod";
}

/** Generate the page body from a chain (pure). Returns null while no version has succeeded. */
export function buildModDoc(chain: ChainBuild[], now = new Date()): CyrusModDoc | null {
  const ok = succeededVersions(chain);
  const cur = currentVersion(chain);
  if (!cur) return null;
  const r = cleanResult(cur.result);
  const s = r?.summary ?? null;
  const versions: CyrusDocVersion[] = ok.map((b, i) => {
    const br = cleanResult(b.result);
    const changes = clip(br?.summary?.changes, 1200);
    return {
      buildId: b.id,
      n: i + 1,
      version: b.version,
      mcVersion: b.mcVersion,
      at: (b.finishedAt ?? b.createdAt).toISOString(),
      notes: changes || (b.changeRequest ? clip(b.changeRequest, 1200) : i === 0 ? "First version." : "Rebuilt."),
      request: clip(b.changeRequest ?? b.prompt, 2000),
      basedOn: b.baseBuildId,
      jarName: b.jarName,
      jarSize: b.jarSize,
      jarSha256: b.jarSha256 ?? null,
      safety: br?.safety?.verdict ?? null,
    };
  }).reverse();
  const mc = [...new Set(ok.map((b) => b.mcVersion))].sort((a, b) => b.localeCompare(a, undefined, { numeric: true }));
  return {
    v: 1,
    name: displayName(chain),
    pluginName: cur.pluginName,
    tagline: clip(s?.tagline, 200) || null,
    summary: clip(s?.text, 4000) || null,
    howToUse: strArr(s?.howToUse, 20, 400),
    limitations: strArr(s?.limitations, 20, 400),
    commands: (r?.commands ?? []).slice(0, 60),
    permissions: (r?.permissions ?? []).slice(0, 80),
    config: (r?.config ?? []).slice(0, 80),
    compat: {
      software: [...CYRUS_SOFTWARE],
      mcVersions: mc,
      note: `Built against the Paper API for Minecraft ${cur.mcVersion}. Runs on Paper and Purpur; not on Spigot, Folia, Fabric or Forge.`,
    },
    versions,
    currentBuildId: cur.id,
    files: (r?.files ?? []).filter((f) => /^src\//.test(f.path)).slice(0, 200),
    generatedAt: now.toISOString(),
  };
}

/** Read a stored doc defensively (old shapes, partial rows). */
export function readModDoc(raw: unknown): CyrusModDoc | null {
  if (!raw || typeof raw !== "object" || (raw as { v?: unknown }).v !== 1) return null;
  const d = raw as CyrusModDoc;
  if (!Array.isArray(d.versions)) return null;
  return d;
}

