/** Deterministic bytes (stable key order, 2-space JSON, trailing newline): unchanged config = identical file. */
export function serializeLoaderConfig(c: LoaderConfig): string {
  const packs = c.packs.map((p) => ({ id: p.id, url: p.url, sha1: p.sha1, ...(p.prompt != null ? { prompt: p.prompt } : {}), required: p.required, ...(p.owner ? { owner: p.owner } : {}), ...(p.role ? { role: p.role } : {}) }));
  return JSON.stringify({ schema: 1, packs }, null, 2) + "\n";
}

/** Plugins known to own the server's resource pack (they build/send their own; ours would stack or be replaced). */
export const KNOWN_PACK_OWNERS = ["ResourcePackManager", "Oraxen", "Nexo", "ItemsAdder", "ForcePack", "ServerResourcePack"] as const;

export type PackChange =
  | { op: "upsert"; namespace: string; role: string; sha1: string; prompt?: string; required?: boolean; owner?: string }
  | { op: "remove"; namespace: string; role: string };
/** What the server inventory knows (data, read elsewhere): installed plugin names, current server.properties. */
export type PackInventory = { plugins?: string[]; serverProperties?: Record<string, string> };

export type PackChangeResult =
  | { ok: true; config: LoaderConfig; action: "added" | "updated" | "unchanged" | "removed" | "absent"; id: string; changed: boolean; warnings: Issue[] }
  | { ok: false; code: string; error: string };

/**
 * Apply one pack change to the loader config. Existing entries keep their position (pack stacking order is the
 * list order); new ones are appended. The URL is always the immutable `/p/<sha1>.zip` for the sha1.
 */
export function applyPackChange(current: LoaderConfig | null, change: PackChange, ctx: { urlFor: (sha1: string) => string }, inv: PackInventory = {}): PackChangeResult {
  let id: string;
  try { id = packIdFor(change.namespace, change.role); } catch (e) { return { ok: false, code: "bad_identity", error: (e as Error).message }; }
  const base: LoaderConfig = current ? { schema: 1, packs: current.packs.map((p) => ({ ...p })) } : { schema: 1, packs: [] };
  const v = validateLoaderConfig(base);
  if (!v.ok) return { ok: false, code: "current_invalid", error: `the server's current pack config is invalid: ${v.errors.map((e) => e.message).join("; ")}` };
  const warnings = inventoryWarnings(inv);
  const idx = base.packs.findIndex((p) => p.id === id);
  if (change.op === "remove") {
    if (idx < 0) return { ok: true, config: base, action: "absent", id, changed: false, warnings };
    base.packs.splice(idx, 1);
    return { ok: true, config: base, action: "removed", id, changed: true, warnings };
  }
  if (!SHA1_RE.test(change.sha1)) return { ok: false, code: "bad_sha1", error: "sha1 must be 40 lower-case hex chars" };
  if (change.prompt != null && change.prompt.length > MAX_PROMPT) return { ok: false, code: "bad_prompt", error: `prompt longer than ${MAX_PROMPT} chars` };
  const entry: LoaderPack = {
    id, url: ctx.urlFor(change.sha1), sha1: change.sha1,
    ...(change.prompt ? { prompt: change.prompt } : {}),
    required: change.required ?? false,
    owner: change.owner ?? change.namespace, role: change.role,
  };
  if (idx < 0) {
    if (base.packs.length >= MAX_PACKS) return { ok: false, code: "too_many", error: `this server already has ${MAX_PACKS} Nxeon packs` };
    base.packs.push(entry);
  } else {
    const same = serializeLoaderConfig({ schema: 1, packs: [base.packs[idx]] }) === serializeLoaderConfig({ schema: 1, packs: [entry] });
    if (same) return { ok: true, config: base, action: "unchanged", id, changed: false, warnings };
    base.packs[idx] = entry;
  }
  const after = validateLoaderConfig(base);
  if (!after.ok) return { ok: false, code: "result_invalid", error: after.errors.map((e) => e.message).join("; ") };
  return { ok: true, config: base, action: idx < 0 ? "added" : "updated", id, changed: true, warnings };
}

function inventoryWarnings(inv: PackInventory): Issue[] {
  const out: Issue[] = [];
  const names = new Set((inv.plugins ?? []).map((n) => n.toLowerCase()));
  for (const o of KNOWN_PACK_OWNERS) {
    if (names.has(o.toLowerCase())) out.push({ code: "pack_owner_present", message: `${o} also manages a resource pack on this server. Nxeon's packs are sent as extra packs; if ${o} replaces all packs on join, ours can be dropped. Merging into ${o}'s pack is not built yet.` });
  }
  const rp = inv.serverProperties?.["resource-pack"];
  if (rp && rp.trim()) out.push({ code: "server_properties_pack", message: "server.properties already sends a resource pack; Nxeon's packs stack on top of it." });
  return out;
}

/**
 * Fallback when the Pack Loader cannot be used: server.properties holds exactly ONE pack. Returns the keys to set
 * (an empty config clears them). More than one pack cannot be expressed this way.
 */
export function serverPropertiesFallback(c: LoaderConfig): { ok: true; keys: Record<string, string> } | { ok: false; error: string } {
  if (c.packs.length > 1) return { ok: false, error: `server.properties can hold one resource pack; this server has ${c.packs.length}. Use the Nxeon Pack Loader.` };
  const p = c.packs[0];
  if (!p) return { ok: true, keys: { "resource-pack": "", "resource-pack-id": "", "resource-pack-sha1": "", "resource-pack-prompt": "", "require-resource-pack": "false" } };
  return {
    ok: true,
    keys: {
      "resource-pack": p.url,
      "resource-pack-id": p.id,
      "resource-pack-sha1": p.sha1,
      // Written as a JSON text component (the 1.20.3+ format as far as we know: UNVERIFIED against a real server); empty = no prompt.
      "resource-pack-prompt": p.prompt ? JSON.stringify({ text: p.prompt }) : "",
      "require-resource-pack": p.required ? "true" : "false",
    },
  };
}

/** Every sha1 a set of configs references (input for pack GC). */
export const referencedSha1s = (configs: LoaderConfig[]): Set<string> => new Set(configs.flatMap((c) => c.packs.map((p) => p.sha1)));
// LocalDiskStore: packs on local disk at <root>/p/<sha1>.zip. For dev, tests and a safe fallback.
// Served in dev by app/p/[file]/route.ts (inert unless this store is the selected one).
import { createHash, randomBytes } from "node:crypto";
import { promises as fsp } from "node:fs";
import path from "node:path";
import { packKey, publicPackUrl, SHA1_RE, type PackObject, type PackStore, type PutResult } from "./types";

export class LocalDiskStore implements PackStore {
  readonly kind = "local" as const;
  constructor(readonly root: string, readonly publicBase: string) {
    if (!path.isAbsolute(root)) throw new Error("LocalDiskStore root must be an absolute path");
    publicPackUrl(publicBase, "0".repeat(40)); // validate the base once
  }
  pathFor(sha1: string): string {
    return path.join(this.root, packKey(sha1));
  }
  async put(sha1: string, bytes: Buffer): Promise<PutResult> {
    const key = packKey(sha1);
    const got = createHash("sha1").update(bytes).digest("hex");
    if (got !== sha1) throw new Error(`content sha1 ${got} does not match ${sha1}`);
    const dest = this.pathFor(sha1);
    if (await this.exists(sha1)) return { sha1, key, size: bytes.length, created: false };
    await fsp.mkdir(path.dirname(dest), { recursive: true });
    const tmp = `${dest}.part-${randomBytes(4).toString("hex")}`;
    await fsp.writeFile(tmp, bytes, { flag: "wx" });
    await fsp.rename(tmp, dest);
    return { sha1, key, size: bytes.length, created: true };
  }
  async exists(sha1: string): Promise<boolean> {
    try { return (await fsp.stat(this.pathFor(sha1))).isFile(); } catch { return false; }
  }
  urlFor(sha1: string): string {
    return publicPackUrl(this.publicBase, sha1);
  }
  async read(sha1: string): Promise<Buffer | null> {
    try { return await fsp.readFile(this.pathFor(sha1)); } catch { return null; }
  }
  async delete(sha1: string): Promise<boolean> {
    try { await fsp.unlink(this.pathFor(sha1)); return true; } catch { return false; }
  }
  async list(): Promise<PackObject[]> {
    const dir = path.join(this.root, "p");
    let names: string[];
    try { names = await fsp.readdir(dir); } catch { return []; }
    const out: PackObject[] = [];
    for (const n of names.sort()) {
      const m = /^([0-9a-f]{40})\.zip$/.exec(n);
      if (!m || !SHA1_RE.test(m[1])) continue;
      const st = await fsp.stat(path.join(dir, n));
      if (st.isFile()) out.push({ sha1: m[1], size: st.size, lastModified: st.mtime });
    }
    return out;
  }
}
