// Publish a built pack zip: size cap, structural check, sha1, idempotent put, immutable public URL.
import { createHash } from "node:crypto";
import { inspectPackZip } from "./zipcheck";
import type { PackObject, PackStore } from "./types";

export type Published = { ok: true; sha1: string; url: string; bytes: number; created: boolean } | { ok: false; code: "too_large" | "empty" | "bad_zip"; error: string };

export async function publishPack(store: PackStore, zip: Buffer, opts: { maxBytes: number }): Promise<Published> {
  if (!zip.length) return { ok: false, code: "empty", error: "the pack is empty" };
  if (zip.length > opts.maxBytes) return { ok: false, code: "too_large", error: `the pack is ${zip.length} bytes; the limit is ${opts.maxBytes}` };
  const z = inspectPackZip(zip);
  if (!z.ok) return { ok: false, code: "bad_zip", error: z.error };
  const sha1 = createHash("sha1").update(zip).digest("hex");
  const r = await store.put(sha1, zip);
  return { ok: true, sha1, url: store.urlFor(sha1), bytes: zip.length, created: r.created };
}

export type GcPlan = { delete: PackObject[]; keptReferenced: number; keptYoung: number };

/** Pure: unreferenced objects last modified more than `olderThanDays` before `now`. */
export function planPackGc(objects: PackObject[], referenced: ReadonlySet<string>, opts: { now: Date; olderThanDays: number }): GcPlan {
  if (!(opts.olderThanDays >= 1)) throw new Error("olderThanDays must be at least 1 (a fresh upload may not be referenced yet)");
  const cutoff = opts.now.getTime() - opts.olderThanDays * 86400_000;
  const plan: GcPlan = { delete: [], keptReferenced: 0, keptYoung: 0 };
  for (const o of objects) {
    if (referenced.has(o.sha1)) plan.keptReferenced++;
    else if (o.lastModified.getTime() > cutoff) plan.keptYoung++;
    else plan.delete.push(o);
  }
  return plan;
}

/** Retention GC. Dry run by default; `maxDeletes` bounds one pass. `referenced` must be complete (every sha1 any config or revision still points at). */
export async function runPackGc(store: PackStore, referenced: ReadonlySet<string>, opts: { now?: Date; olderThanDays: number; dryRun?: boolean; maxDeletes?: number }) {
  const plan = planPackGc(await store.list(), referenced, { now: opts.now ?? new Date(), olderThanDays: opts.olderThanDays });
  const todo = plan.delete.slice(0, opts.maxDeletes ?? 500);
  const deleted: string[] = [];
  if (opts.dryRun !== false) return { ...plan, deleted, dryRun: true };
  for (const o of todo) if (await store.delete(o.sha1)) deleted.push(o.sha1);
  return { ...plan, deleted, dryRun: false };
}
// Which pack store to use, from env only. Fail closed: production with nothing configured has NO store
// (pack delivery is off), never a silent fallback to the app server's disk.
//
//   CYRUS_PACK_STORE          local | s3 | off   (default: local outside production, off in production)
//   CYRUS_PACK_PUBLIC_BASE    public base URL clients download from, e.g. https://packs.<nxeon domain>
//                             (default for local: http://localhost:3000, served by app/p/[file]/route.ts)
//   CYRUS_PACK_MAX_BYTES      hard cap per pack (default 100 MB)
//   CYRUS_PACK_LOCAL_DIR      local store root (absolute; default <cwd>/.data/cyrus-packs)
//   CYRUS_PACK_S3_ENDPOINT, CYRUS_PACK_S3_BUCKET, CYRUS_PACK_S3_REGION (default "auto"),
//   CYRUS_PACK_S3_ACCESS_KEY_ID, CYRUS_PACK_S3_SECRET_ACCESS_KEY, CYRUS_PACK_S3_PREFIX (optional)
import path from "node:path";
import { LocalDiskStore } from "./local";
import { S3Store } from "./s3";
import { DEFAULT_MAX_PACK_BYTES, type PackStore } from "./types";

type Env = Record<string, string | undefined>;
export type StoreSelection = { ok: true; store: PackStore; maxBytes: number } | { ok: false; reason: string };

export function maxPackBytes(env: Env = process.env): number {
  const v = env.CYRUS_PACK_MAX_BYTES;
  if (v == null || v === "") return DEFAULT_MAX_PACK_BYTES;
  const n = Number(v);
  if (!Number.isInteger(n) || n < 1024 || n > 1024 * 1024 * 1024) throw new Error("CYRUS_PACK_MAX_BYTES must be an integer between 1 KB and 1 GB");
  return n;
}

export function selectPackStore(env: Env = process.env, opts: { fetch?: typeof fetch } = {}): StoreSelection {
  const prod = env.NODE_ENV === "production";
  const kind = (env.CYRUS_PACK_STORE || (prod ? "off" : "local")).toLowerCase();
  try {
    const maxBytes = maxPackBytes(env);
    if (kind === "off") return { ok: false, reason: "pack hosting is off (CYRUS_PACK_STORE unset or off)" };
    if (kind === "local") {
      const root = env.CYRUS_PACK_LOCAL_DIR || path.join(process.cwd(), ".data/cyrus-packs");
      return { ok: true, store: new LocalDiskStore(root, env.CYRUS_PACK_PUBLIC_BASE || "http://localhost:3000"), maxBytes };
    }
    if (kind === "s3") {
      const need = ["CYRUS_PACK_S3_ENDPOINT", "CYRUS_PACK_S3_BUCKET", "CYRUS_PACK_S3_ACCESS_KEY_ID", "CYRUS_PACK_S3_SECRET_ACCESS_KEY", "CYRUS_PACK_PUBLIC_BASE"].filter((k) => !env[k]);
      if (need.length) return { ok: false, reason: `s3 pack store is missing ${need.join(", ")}` };
      return {
        ok: true,
        maxBytes,
        store: new S3Store({
          endpoint: env.CYRUS_PACK_S3_ENDPOINT!, bucket: env.CYRUS_PACK_S3_BUCKET!, region: env.CYRUS_PACK_S3_REGION || "auto",
          credentials: { accessKeyId: env.CYRUS_PACK_S3_ACCESS_KEY_ID!, secretAccessKey: env.CYRUS_PACK_S3_SECRET_ACCESS_KEY! },
          publicBase: env.CYRUS_PACK_PUBLIC_BASE!, prefix: env.CYRUS_PACK_S3_PREFIX || undefined, fetch: opts.fetch,
        }),
      };
    }
    return { ok: false, reason: `unknown CYRUS_PACK_STORE ${kind}` };
  } catch (e) {
    return { ok: false, reason: (e as Error).message };
  }
}
// Pack install logic (pure). Computes the Nxeon Pack Loader config (plugins/NxeonPackLoader/packs.json) when a mod's
// resource pack is added, updated or removed, plus the single-pack server.properties fallback.
// The plugin (services/modbuilder/tools/packloader) applies the SAME validation rules; keep them in step.
import { createHash } from "node:crypto";
import { SHA1_RE } from "./types";

export const LOADER_CONFIG_SCHEMA = 1;
export const LOADER_CONFIG_PATH = "plugins/NxeonPackLoader/packs.json";
export const MAX_PACKS = 16;
export const MAX_PROMPT = 300;
export const MAX_URL = 1000;
/** Fixed namespace for name-based pack UUIDs. Never change it: every installed pack id derives from it. */
export const NXEON_PACK_UUID_NAMESPACE = "a6b1f0d2-7c3e-4b59-9e14-2f8d6c0a5b37";
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const ROLE_RE = /^[a-z][a-z0-9_-]{0,31}$/;
const NS_RE = /^[a-z][a-z0-9_]{1,31}$/;

export type LoaderPack = {
  /** Stable per (project namespace, pack role): uuidV5(NXEON_PACK_UUID_NAMESPACE, "<namespace>:<role>"). */
  id: string;
  /** Immutable content URL (`<base>/p/<sha1>.zip`). */
  url: string;
  sha1: string;
  prompt?: string;
  /** true = the client must accept or is disconnected (Paper `force`). */
  required: boolean;
  /** Nxeon bookkeeping, ignored by the plugin. */
  owner?: string;
  role?: string;
};
export type LoaderConfig = { schema: 1; packs: LoaderPack[] };
export type Issue = { code: string; message: string };

/** RFC 4122 version 5 (SHA-1, name-based) UUID. */
export function uuidV5(namespace: string, name: string): string {
  if (!UUID_RE.test(namespace)) throw new Error("bad namespace uuid");
  const ns = Buffer.from(namespace.replace(/-/g, ""), "hex");
  const h = createHash("sha1").update(Buffer.concat([ns, Buffer.from(name, "utf8")])).digest().subarray(0, 16);
  h[6] = (h[6] & 0x0f) | 0x50;
  h[8] = (h[8] & 0x3f) | 0x80;
  const x = h.toString("hex");
  return `${x.slice(0, 8)}-${x.slice(8, 12)}-${x.slice(12, 16)}-${x.slice(16, 20)}-${x.slice(20)}`;
}

export const packIdFor = (namespace: string, role: string): string => {
  if (!NS_RE.test(namespace)) throw new Error(`bad project namespace ${namespace}`);
  if (!ROLE_RE.test(role)) throw new Error(`bad pack role ${role}`);
  return uuidV5(NXEON_PACK_UUID_NAMESPACE, `${namespace}:${role}`);
};

/** Same rules as the plugin's PackConfig.parse: any problem rejects the WHOLE config (fail safe: nothing is sent). */
export function validateLoaderConfig(raw: unknown, opts: { requireHttps?: boolean } = {}): { ok: true; config: LoaderConfig } | { ok: false; errors: Issue[] } {
  const errors: Issue[] = [];
  const o = raw as Record<string, unknown>;
  if (!o || typeof o !== "object" || Array.isArray(o)) return { ok: false, errors: [{ code: "not_object", message: "config must be a JSON object" }] };
  if (o.schema !== LOADER_CONFIG_SCHEMA) errors.push({ code: "schema", message: `schema must be ${LOADER_CONFIG_SCHEMA}` });
  if (!Array.isArray(o.packs)) return { ok: false, errors: [...errors, { code: "packs", message: "packs must be an array" }] };
  if (o.packs.length > MAX_PACKS) errors.push({ code: "too_many", message: `at most ${MAX_PACKS} packs` });
