"use strict";
// Texture specs in the build service (Cyrus R1 asset slice). The model writes small declarative TEXTURE SPEC files
// (assets/textures/<name>.json, the Nxeon texture DSL); this module validates them, renders them and runs the
// quality bar, so a bad spec goes back to the model as repair feedback just like a compile error. The portal renders
// the real pack from the returned specs with its own TypeScript copy (lib/cyrus/textures); the two MUST agree:
//   checkSpec  == lib/cyrus/textures/dsl.ts checkSpec
//   render     == lib/cyrus/textures/render.ts render (byte for byte)
//   quality    == lib/cyrus/textures/quality.ts textureQuality
// test/cyrus-assets.test.ts runs both on the shared fixtures in test/fixtures/cyrus-textures. Change both or neither.
// Plain Node, no dependencies, no I/O except the workspace helpers at the bottom.

const fs = require("fs");
const path = require("path");

const TEXTURE_SIZES = [16, 32, 64];
const MAX_OPS = 400;
const MAX_PALETTE = 24;
const MAX_TEXTURES = 24;
const MAX_SPEC_BYTES = 64 * 1024;
const HEX = /^#[0-9a-fA-F]{6}$/;
const KEY = /^[a-z][a-z0-9_]{0,23}$/;
const NAME = /^[a-z][a-z0-9_]{1,31}$/;
const NAMESPACE_RE = /^nx_[a-z0-9]{8}$/;
const TEXTURE_DIR = "assets/textures";
const TEXTURE_FILE_RE = /^assets\/textures\/[a-z][a-z0-9_]{1,31}\.json$/;

const num = (v, lo, hi) => typeof v === "number" && Number.isFinite(v) && v >= lo && v <= hi;

/** Port of lib/cyrus/textures/dsl.ts checkSpec: same checks, same order, same messages. */
function checkSpec(raw) {
  if (!raw || typeof raw !== "object") return { ok: false, error: "texture must be an object" };
  const r = raw;
  if (typeof r.name !== "string" || !NAME.test(r.name)) return { ok: false, error: "name must be lowercase letters, digits and underscores (2-32 chars)" };
  if (!TEXTURE_SIZES.includes(r.size)) return { ok: false, error: "size must be 16, 32 or 64" };
  const size = r.size;
  if (!r.palette || typeof r.palette !== "object") return { ok: false, error: "palette is required" };
  const palette = {};
  const entries = Object.entries(r.palette);
  if (entries.length === 0 || entries.length > MAX_PALETTE) return { ok: false, error: `palette needs 1-${MAX_PALETTE} colours` };
  for (const [k, v] of entries) {
    if (!KEY.test(k)) return { ok: false, error: `bad palette key ${k}` };
    if (typeof v !== "string" || !HEX.test(v)) return { ok: false, error: `palette ${k} must be #rrggbb` };
    palette[k] = v.toLowerCase();
  }
  if (!Array.isArray(r.ops) || r.ops.length === 0 || r.ops.length > MAX_OPS) return { ok: false, error: `ops needs 1-${MAX_OPS} entries` };
  const col = (c) => typeof c === "string" && c in palette;
  const pos = (v) => num(v, -size, size * 2);
  const ops = [];
  for (const [i, o] of r.ops.entries()) {
    const at = `ops[${i}]`;
    if (!o || typeof o !== "object") return { ok: false, error: `${at} must be an object` };
    const p = o;
    switch (p.op) {
      case "fill": if (!col(p.c)) return { ok: false, error: `${at}: unknown colour` }; ops.push({ op: "fill", c: p.c }); break;
      case "px": if (!pos(p.x) || !pos(p.y) || !col(p.c)) return { ok: false, error: `${at}: bad px` }; ops.push({ op: "px", x: p.x, y: p.y, c: p.c }); break;
      case "rect": if (![p.x, p.y].every(pos) || !num(p.w, 0, size * 2) || !num(p.h, 0, size * 2) || !col(p.c)) return { ok: false, error: `${at}: bad rect` }; ops.push({ op: "rect", x: p.x, y: p.y, w: p.w, h: p.h, c: p.c }); break;
      case "line": if (![p.x1, p.y1, p.x2, p.y2].every(pos) || !col(p.c)) return { ok: false, error: `${at}: bad line` }; ops.push({ op: "line", x1: p.x1, y1: p.y1, x2: p.x2, y2: p.y2, c: p.c }); break;
      case "circle": if (!pos(p.x) || !pos(p.y) || !num(p.r, 0, size) || !col(p.c)) return { ok: false, error: `${at}: bad circle` }; ops.push({ op: "circle", x: p.x, y: p.y, r: p.r, c: p.c, ring: p.ring === true }); break;
      case "poly": {
        if (!Array.isArray(p.pts) || p.pts.length < 3 || p.pts.length > 40 || !col(p.c)) return { ok: false, error: `${at}: poly needs 3-40 points and a colour` };
        const pts = [];
        for (const q of p.pts) { if (!Array.isArray(q) || q.length !== 2 || !pos(q[0]) || !pos(q[1])) return { ok: false, error: `${at}: bad point` }; pts.push([q[0], q[1]]); }
        ops.push({ op: "poly", pts, c: p.c }); break;
      }
      case "gradient": if (![p.x, p.y].every(pos) || !num(p.w, 0, size * 2) || !num(p.h, 0, size * 2) || !col(p.c1) || !col(p.c2)) return { ok: false, error: `${at}: bad gradient` }; ops.push({ op: "gradient", x: p.x, y: p.y, w: p.w, h: p.h, c1: p.c1, c2: p.c2, dir: p.dir === "h" ? "h" : "v" }); break;
      case "noise": if (!num(p.amount, 0, 60)) return { ok: false, error: `${at}: noise amount 0-60` }; ops.push({ op: "noise", amount: p.amount, seed: num(p.seed, 0, 1e9) ? p.seed : 1, ...(num(p.x, 0, size) && num(p.y, 0, size) && num(p.w, 0, size) && num(p.h, 0, size) ? { x: p.x, y: p.y, w: p.w, h: p.h } : {}) }); break;
      case "shade": ops.push({ op: "shade", amount: num(p.amount, 0, 60) ? p.amount : 28 }); break;
      case "outline": if (!col(p.c)) return { ok: false, error: `${at}: unknown colour` }; ops.push({ op: "outline", c: p.c }); break;
      default: return { ok: false, error: `${at}: unknown op ${String(p.op)}` };
    }
  }
  return { ok: true, spec: { name: r.name, size, palette, mirror: r.mirror === true, ops } };
}

// ---------------------------------------------------------------- render (port of render.ts)
const rgb = (hex) => [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
const clamp = (v) => Math.max(0, Math.min(255, Math.round(v)));
function rng(seed) { let s = (seed >>> 0) || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; }; }

function render(spec) {
  const n = spec.size;
  const px = new Uint8ClampedArray(n * n * 4);
  const P = (k) => rgb(spec.palette[k]);
  const set = (x, y, c) => {
    x = Math.round(x); y = Math.round(y);
    if (x < 0 || y < 0 || x >= n || y >= n) return;
    const i = (y * n + x) * 4; px[i] = c[0]; px[i + 1] = c[1]; px[i + 2] = c[2]; px[i + 3] = 255;
  };
  const opaque = (x, y) => x >= 0 && y >= 0 && x < n && y < n && px[(y * n + x) * 4 + 3] > 0;
  const draw = (o) => {
    switch (o.op) {
      case "fill": { const c = P(o.c); for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) set(x, y, c); break; }
      case "px": set(o.x, o.y, P(o.c)); break;
      case "rect": { const c = P(o.c); for (let y = Math.floor(o.y); y < Math.floor(o.y) + o.h; y++) for (let x = Math.floor(o.x); x < Math.floor(o.x) + o.w; x++) set(x, y, c); break; }
      case "line": {
        const c = P(o.c); let x0 = Math.round(o.x1), y0 = Math.round(o.y1); const x1 = Math.round(o.x2), y1 = Math.round(o.y2);
        const dx = Math.abs(x1 - x0), dy = -Math.abs(y1 - y0), sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1; let err = dx + dy;
        for (let guard = 0; guard < 4096; guard++) { set(x0, y0, c); if (x0 === x1 && y0 === y1) break; const e2 = 2 * err; if (e2 >= dy) { err += dy; x0 += sx; } if (e2 <= dx) { err += dx; y0 += sy; } }
        break;
      }
      case "circle": {
        const c = P(o.c);
        for (let y = Math.floor(o.y - o.r - 1); y <= Math.ceil(o.y + o.r + 1); y++) for (let x = Math.floor(o.x - o.r - 1); x <= Math.ceil(o.x + o.r + 1); x++) {
          const d = Math.hypot(x + 0.5 - o.x, y + 0.5 - o.y);
          if (o.ring ? d <= o.r && d > o.r - 1.2 : d <= o.r) set(x, y, c);
        }
        break;
      }
      case "poly": {
        const c = P(o.c); const ys = o.pts.map((p) => p[1]); const y0 = Math.max(0, Math.floor(Math.min(...ys))), y1 = Math.min(n - 1, Math.ceil(Math.max(...ys)));
        for (let y = y0; y <= y1; y++) {
          const yc = y + 0.5; const xs = [];
          for (let i = 0; i < o.pts.length; i++) {
            const [ax, ay] = o.pts[i], [bx, by] = o.pts[(i + 1) % o.pts.length];
            if ((ay <= yc && by > yc) || (by <= yc && ay > yc)) xs.push(ax + ((yc - ay) / (by - ay)) * (bx - ax));
          }
          xs.sort((a, b) => a - b);
          for (let k = 0; k + 1 < xs.length; k += 2) for (let x = Math.ceil(xs[k] - 0.5); x <= Math.floor(xs[k + 1] - 0.5); x++) set(x, y, c);
        }
        break;
      }
      case "gradient": {
        const a = P(o.c1), b = P(o.c2);
        for (let y = Math.floor(o.y); y < Math.floor(o.y) + o.h; y++) for (let x = Math.floor(o.x); x < Math.floor(o.x) + o.w; x++) {
          const t = o.dir === "h" ? (o.w <= 1 ? 0 : (x - Math.floor(o.x)) / (o.w - 1)) : (o.h <= 1 ? 0 : (y - Math.floor(o.y)) / (o.h - 1));
          set(x, y, [clamp(a[0] + (b[0] - a[0]) * t), clamp(a[1] + (b[1] - a[1]) * t), clamp(a[2] + (b[2] - a[2]) * t)]);
        }
        break;
      }
      case "noise": {
        const r = rng(o.seed ?? 1); const x0 = o.x ?? 0, y0 = o.y ?? 0, w = o.w ?? n, h = o.h ?? n;
        for (let y = y0; y < y0 + h; y++) for (let x = x0; x < x0 + w; x++) {
          const i = (y * n + x) * 4; const d = (r() - 0.5) * 2 * o.amount;
          if (px[i + 3] > 0) { px[i] = clamp(px[i] + d); px[i + 1] = clamp(px[i + 1] + d); px[i + 2] = clamp(px[i + 2] + d); }
        }
        break;
      }
      case "shade": {
        const a = o.amount ?? 28; const src = px.slice();
        const has = (x, y) => x >= 0 && y >= 0 && x < n && y < n && src[(y * n + x) * 4 + 3] > 0;
        for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
          if (!has(x, y)) continue; const i = (y * n + x) * 4; let d = 0;
          if (!has(x, y - 1) || !has(x - 1, y)) d += a; if (!has(x, y + 1) || !has(x + 1, y)) d -= a;
          px[i] = clamp(px[i] + d); px[i + 1] = clamp(px[i + 1] + d); px[i + 2] = clamp(px[i + 2] + d);
        }
        break;
      }
      case "outline": {
