          if (opaque(x + 1, y) || opaque(x - 1, y) || opaque(x, y + 1) || opaque(x, y - 1)) add.push([x, y]);
        }
        for (const [x, y] of add) set(x, y, c);
        break;
      }
    }
  };
  const mirrorNow = () => { for (let y = 0; y < n; y++) for (let x = 0; x < n / 2; x++) { const a = (y * n + x) * 4, b = (y * n + (n - 1 - x)) * 4; if (px[a + 3]) { px[b] = px[a]; px[b + 1] = px[a + 1]; px[b + 2] = px[a + 2]; px[b + 3] = px[a + 3]; } } };
  for (const o of spec.ops) { draw(o); if (spec.mirror && o.op !== "outline") mirrorNow(); }
  return { size: n, px };
}

// ---------------------------------------------------------------- quality (port of quality.ts)
const QUALITY_VERSION = "tq-1";
const PALETTE_LIMIT = { 16: { warn: 32, fail: 48 }, 32: { warn: 48, fail: 96 }, 64: { warn: 64, fail: 128 } };
const GRAIN_MAX = 24;
const GRAIN = { warn: 0.2, fail: 0.35 };
const CONTRAST = { fail: 1.6, warn: 2.5 };
const COVERAGE = { failLow: 0.04, warnLow: 0.1, warnHigh: 0.85 };
const OUTLINE_DARK = 0.12;
const OUTLINE_WARN = 0.5;
const lin = (c) => { const s = c / 255; return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4); };
const lum = (r, g, b) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
const r4 = (v) => Math.round(v * 10000) / 10000;

function textureQuality(img) {
  const n = img.size, px = img.px;
  const at = (x, y) => (y * n + x) * 4;
  const opaque = (x, y) => x >= 0 && y >= 0 && x < n && y < n && px[at(x, y) + 3] === 255;
  const dist = (a, b) => Math.hypot(px[a] - px[b], px[a + 1] - px[b + 1], px[a + 2] - px[b + 2]);
  let count = 0, partial = 0, lo = Infinity, hi = -Infinity, pairs = 0, grain = 0, rim = 0, rimDark = 0;
  const colours = new Set();
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const i = at(x, y), a = px[i + 3];
    if (a !== 0 && a !== 255) partial++;
    if (a !== 255) continue;
    count++;
    colours.add((px[i] << 16) | (px[i + 1] << 8) | px[i + 2]);
    const L = lum(px[i], px[i + 1], px[i + 2]);
    if (L < lo) lo = L;
    if (L > hi) hi = L;
    let edgeOfShape = false;
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      if (!opaque(x + dx, y + dy)) { edgeOfShape = true; continue; }
      if (dx < 0 || dy < 0) continue;
      pairs++;
      const d = dist(i, at(x + dx, y + dy));
      if (d > 0 && d <= GRAIN_MAX) grain++;
