    if (edgeOfShape) { rim++; if (L <= OUTLINE_DARK) rimDark++; }
  }
  const total = n * n;
  const checks = [];
  const lim = PALETTE_LIMIT[n] || PALETTE_LIMIT[64];
  const coverage = count / total;
  if (partial > 0) checks.push({ id: "transparency", status: "fail", value: partial, limit: "alpha 0 or 255 only", message: `${partial} pixels are semi-transparent; item textures use fully clear or fully solid pixels` });
  else if (coverage < COVERAGE.failLow) checks.push({ id: "transparency", status: "fail", value: r4(coverage), limit: `coverage >= ${COVERAGE.failLow}`, message: "the texture is almost empty; draw the item so it fills a good part of the canvas" });
  else if (count === total) checks.push({ id: "transparency", status: "fail", value: 1, limit: "some clear pixels", message: "every pixel is solid, so the item shows as a square tile; leave the background transparent around the item's silhouette" });
  else if (coverage < COVERAGE.warnLow || coverage > COVERAGE.warnHigh) checks.push({ id: "transparency", status: "warn", value: r4(coverage), limit: `${COVERAGE.warnLow}-${COVERAGE.warnHigh}`, message: coverage < COVERAGE.warnLow ? "the item is very small on its canvas" : "the item covers almost the whole canvas" });
  else checks.push({ id: "transparency", status: "pass", value: r4(coverage), limit: `${COVERAGE.warnLow}-${COVERAGE.warnHigh}`, message: "clear background, solid silhouette" });
  const pal = colours.size;
  checks.push({
    id: "palette_size", status: pal > lim.fail ? "fail" : pal > lim.warn ? "warn" : "pass", value: pal, limit: `<= ${lim.warn} (fail above ${lim.fail})`,
    message: pal > lim.fail ? `${pal} distinct colours; vanilla-style art uses a few short shade ramps (reduce noise and gradients)` : pal > lim.warn ? `${pal} distinct colours is on the busy side` : `${pal} distinct colours`,
  });
  const contrast = count ? (hi + 0.05) / (lo + 0.05) : 0;
  checks.push({
    id: "contrast", status: count === 0 || contrast < CONTRAST.fail ? "fail" : contrast < CONTRAST.warn ? "warn" : "pass", value: r4(contrast), limit: `>= ${CONTRAST.warn} (fail below ${CONTRAST.fail})`,
    message: contrast < CONTRAST.fail ? "light and dark are too close, the item will read as a flat blob; add a dark outline and a highlight" : contrast < CONTRAST.warn ? "low contrast between the darkest and lightest shades" : "clear light and dark shades",
  });
