}
const qualityProblems = (r) => r.checks.filter((c) => c.status === "fail").map((c) => `${c.id}: ${c.message} (value ${c.value}, limit ${c.limit})`);

/** Canonical JSON (sorted keys at every level): the bytes whose sha256 identifies a spec on both sides. */
function canonicalJson(v) {
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(",")}]`;
  if (v && typeof v === "object") return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(v[k])}`).join(",")}}`;
  return JSON.stringify(v);
