// ---------------------------------------------------------------- workspace (service only)
/** Texture spec files in a workspace: [{ rel, abs, size }] (sorted). Anything else under assets/ is not a spec. */
function listSpecFiles(ws) {
  const dir = path.join(ws, TEXTURE_DIR);
  let names = [];
  try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; }
  return names.filter((e) => e.isFile()).map((e) => `${TEXTURE_DIR}/${e.name}`).filter((rel) => TEXTURE_FILE_RE.test(rel)).sort()
    .map((rel) => ({ rel, abs: path.join(ws, rel), size: fs.statSync(path.join(ws, rel)).size }));
