/** Snapshot of the spec files (rel -> bytes): what a change build must keep when the plan cannot edit textures. */
function snapshotSpecs(ws) {
  const out = new Map();
  for (const f of listSpecFiles(ws)) out.set(f.rel, fs.readFileSync(f.abs));
  return out;
}

/** String literals in the Java sources (for the "does the plugin use this texture" cross-check). */
function javaLiterals(javaFiles) {
  const lits = new Set();
  for (const f of javaFiles) {
    let text = "";
    try { text = fs.readFileSync(f.abs, "utf8"); } catch { continue; }
