/**
 * Validate every texture spec in the workspace. Returns per-file results plus the repair problems:
 * invalid JSON / spec, failing quality checks, a spec whose file name differs from its name, too many textures,
 * and plugin cross-checks (the namespace literal must appear, every texture must be referenced, no foreign nx_ namespace).
 */
function checkWorkspaceTextures(ws, { namespace, javaFiles = [] }) {
  const files = listSpecFiles(ws);
  const results = [];
  const problems = [];
  if (files.length > MAX_TEXTURES) problems.push(`${files.length} texture files; the limit is ${MAX_TEXTURES}. Merge or drop some.`);
  for (const f of files.slice(0, MAX_TEXTURES)) {
    const want = path.basename(f.rel, ".json");
    const r = { rel: f.rel, name: want, ok: false, problems: [] };
    results.push(r);
    if (f.size > MAX_SPEC_BYTES) { r.problems.push(`${f.rel} is larger than ${MAX_SPEC_BYTES / 1024} KB`); continue; }
    let json;
    try { json = JSON.parse(fs.readFileSync(f.abs, "utf8")); } catch (e) { r.problems.push(`${f.rel} is not valid JSON: ${String(e.message).slice(0, 160)}`); continue; }
    const c = checkSpec(json);
    if (!c.ok) { r.problems.push(`${f.rel}: ${c.error}`); continue; }
    if (c.spec.name !== want) { r.problems.push(`${f.rel}: "name" is "${c.spec.name}" but the file is ${want}.json; they must match`); continue; }
    const quality = textureQuality(render(c.spec));
    r.spec = c.spec; r.quality = quality;
    r.sha256 = require("crypto").createHash("sha256").update(canonicalJson(c.spec)).digest("hex");
    for (const p of qualityProblems(quality)) r.problems.push(`${f.rel} quality ${p}`);
  }
  if (files.length && javaFiles.length) {
    const lits = javaLiterals(javaFiles);
