function assetRound(ws, rec, st, repairs) {
  if (!(rec.assets && rec.assets.texture)) return null;
  const java = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
  const t = TX.checkWorkspaceTextures(ws, { namespace: rec.assets.namespace, javaFiles: java });
  if (!t.files.length) return null;
  const canRepair = st.assetRepairs < MAX_ASSET_REPAIRS && repairs < MAX_REPAIRS;
  const soft = st.softAsked ? [] : t.soft;
  if (canRepair && (t.problems.length || soft.length)) {
    if (soft.length) st.softAsked = true;
    const lines = [...t.problems, ...soft];
    return { kind: "asset", count: lines.length, text: lines.map((p) => `- ${p}`).join("\\n"), say: `Texture check found ${lines.length} problem${lines.length > 1 ? "s" : ""}` };
