 * The `assets` field of POST /builds (the portal's plan-tier gate decided it; the service only re-checks the version).
 * Absent/null -> null (pre-R1 behaviour). A malformed field is a 400, never silently ignored. Textures on a version
 * without item model definitions are switched off here too (defence in depth), with a note.
 */
function parseAssetsRequest(raw, mcVersion, itemModelVersions) {
  if (raw === undefined || raw === null) return null;
  if (typeof raw !== "object" || Array.isArray(raw)) return { error: "assets must be an object" };
  for (const k of Object.keys(raw)) if (!["texture", "sound", "namespace", "version"].includes(k)) return { error: `unknown assets field ${k}` };
  if (raw.texture !== undefined && typeof raw.texture !== "boolean") return { error: "assets.texture must be true or false" };
  if (raw.sound !== undefined && typeof raw.sound !== "boolean") return { error: "assets.sound must be true or false" };
  if (typeof raw.namespace !== "string" || !NAMESPACE_RE.test(raw.namespace)) return { error: "assets.namespace must be a reserved nx_ namespace" };
  const notes = [];
  let texture = raw.texture === true;
  if (texture && !itemModelVersions.has(mcVersion)) { texture = false; notes.push(`textures are off: Minecraft ${mcVersion} has no item model definitions`); }
  return { texture, sound: raw.sound === true, namespace: raw.namespace, notes };
}

