export type GuestOpener = (serverId: string) => Promise<{ fs: GuestFs; server: ServerFacts; close?: () => void }>;

/**
 * Real installer through the Mods engine. Must run where the engine runs (the worker, under its per-server lock).
 * Refuses everything unless CYRUS_MANAGED_PLUGINS_REAL=1.
 */
export function engineManagedInstaller(deps: { open: GuestOpener; readArtifact?: (e: CatalogEntry) => Promise<Buffer>; env?: Record<string, string | undefined> }): ManagedInstaller {
  const env = deps.env ?? process.env;
  const off = () => env[MANAGED_REAL_FLAG] !== "1";
  const OFF = { ok: false as const, error: `managed plugin installs are switched off (${MANAGED_REAL_FLAG} is not 1); nothing was changed` };
  return {
    async install(req) {
      if (off()) return OFF;
      let bytes: Buffer;
      try { bytes = await (deps.readArtifact ?? readManagedArtifact)(req.entry); } catch (e) { return { ok: false, error: (e as Error).message }; }
      const g = await deps.open(req.serverId);
      try {
        const engineDeps: EngineDeps = { fs: g.fs, fetcher: noNetwork };
        const r = await installOrUpdate(managedFamilyInstaller(req.entry, bytes), managedFacts(req.entry), g.server, engineDeps, req.previousVersion ? "update" : "install");
        if (!r.ok) return r;
        return { ok: true, version: req.entry.version, sha256: req.entry.sha256, notes: [...r.changed, ...r.notes] };
      } finally { g.close?.(); }
    },
    async remove(req) {
      if (off()) return OFF;
      const g = await deps.open(req.serverId);
      try {
        const facts = managedFacts({ key: req.key, displayName: req.key });
        // uninstall() never resolves, so the stub entry/bytes are not used for anything but the type.
        const stub = { key: req.key, displayName: req.key, family: "1.21", version: req.version ?? "0", pluginName: req.pluginName ?? req.key, source: "nxeon-built", sourceRef: "-", sha256: "0".repeat(64), artifact: "-", javaRelease: 21 } as CatalogEntry;
        const r = await uninstall(managedFamilyInstaller(stub, Buffer.alloc(0)), facts, g.server, { fs: g.fs, fetcher: noNetwork });
        return r.ok ? { ok: true, notes: [...r.changed, ...r.notes] } : r;
      } finally { g.close?.(); }
    },
  };
}
