// Cyrus R1: what the PORTAL does with the texture specs a succeeded build returns (called from the ModBuild sync path,
// lib/modbuilder/store.ts, so it runs in the API routes and the worker sweep alike). In order:
//   1. re-validate, render and quality-check every spec (lib/cyrus/assets/textures.ts); failures are dropped, never shipped
//   2. build the deterministic resource pack through the version registry (lib/cyrus/textures/pack.ts, NO allowPreview)
//   3. publish it to the pack store (lib/cyrus/packhost; off in production until the owner configures storage)
//   4. compute the Pack Loader entry with the pure applyPackChange
//   5. record one CyrusRevision (kind generated, manifest with jar + spec + pack hashes, engine record) and one
//      CyrusProjectAsset per texture (provenance carries the spec and its quality report)
// Idempotent: re-running for the same build finds its revision (by modBuildId) and the content-addressed asset rows
// and the immutable pack object, so nothing is duplicated. Dependencies are injected (./sync-deps.ts has the real ones).
import type { MbAssets } from "../../modbuilder/types";
import type { SvcAssetResult } from "../../modbuilder/client";
import type { AddRevisionInput, RecordAssetInput } from "../engine-core/store";
import type { ManifestEntry } from "../engine-core/revisions";
import type { StoreSelection } from "../packhost/config";
import { applyPackChange } from "../packhost/loader-config";
import { publishPack } from "../packhost/publish";
import { buildPack } from "../textures/pack";
import { QUALITY_VERSION } from "../textures/quality";
import { checkReturnedTexture, sha256Hex } from "./textures";

export const PACK_ROLE = "main";
export const TEXTURE_SPEC_MIME = "application/vnd.nxeon.texture-spec+json";

export type ProjectRow = { id: string; namespace: string; userId: string };
export type AssetSyncDeps = {
  selectStore: () => StoreSelection;
  projectForRootBuild: (rootBuildId: string) => Promise<ProjectRow | null>;
  createProject: (i: { userId: string; game: string; rootBuildId: string }) => Promise<ProjectRow>;
  findRevisionForBuild: (projectId: string, modBuildId: string) => Promise<{ id: string } | null>;
  headRevisionId: (projectId: string) => Promise<string | null>;
  addRevision: (projectId: string, input: AddRevisionInput) => Promise<{ id: string }>;
  recordAsset: (projectId: string, a: RecordAssetInput) => Promise<unknown>;
};

export type SyncBuild = { id: string; userId: string; rootBuildId: string | null; mcVersion: string; pluginName: string | null; jarName: string | null; jarSha256: string | null };

const clip = (s: string, n: number) => (s.length > n ? s.slice(0, n - 1) + "…" : s);

export async function syncBuildAssets(build: SyncBuild, ar: SvcAssetResult | null | undefined, deps: AssetSyncDeps): Promise<MbAssets | null> {
  if (!ar || (!ar.textures?.length && !ar.downgraded?.length)) return null;
  const root = build.rootBuildId ?? build.id;
  let project = await deps.projectForRootBuild(root);
  if (!project) {
    // A kept-texture change on a chain made before its project existed; create it (same reserved namespace rules).
    try { project = await deps.createProject({ userId: build.userId, game: "minecraft", rootBuildId: root }); }
    catch { project = await deps.projectForRootBuild(root); }
  }
  if (!project) throw new Error(`no Cyrus project for build chain ${root}`);
  const base: MbAssets = { status: "none", namespace: project.namespace, projectId: project.id, revisionId: null, textures: [], dropped: [...(ar.downgraded ?? [])].slice(0, 24), pack: null, loader: null, notices: [...(ar.warnings ?? [])].slice(0, 20) };
  if (ar.namespace && ar.namespace !== project.namespace) {
    return { ...base, status: "failed", notices: [...base.notices, "The custom textures were made for a different namespace than this mod's, so they were not shipped."] };
  }

  // 1. never trust the service: validate, render and quality-check again
  const ok: Extract<ReturnType<typeof checkReturnedTexture>, { ok: true }>[] = [];
  for (const t of (ar.textures ?? []).slice(0, 24)) {
    const c = checkReturnedTexture(t);
    if (!c.ok) { base.dropped.push({ name: c.name, reason: c.reason }); base.notices.push(`Custom texture "${c.name}" was left out: it did not pass Nxeon's texture checks.`); continue; }
    if (ok.some((x) => x.name === c.name)) continue;
    ok.push(c);
  }
  if (!ok.length) return base;
  const name = build.pluginName || "this mod";

  // 2. the deterministic pack, through the registry (preview versions refused: no allowPreview in this path)
  const built = buildPack({ namespace: project.namespace, description: clip(`${name}: custom textures by Cyrus`, 100), mcVersion: build.mcVersion, textures: ok.map((c) => c.spec) });
  const textures = ok.map((c) => ({ name: c.name, model: `${project!.namespace}:${c.name}`, specSha256: c.specSha256, pngSha256: c.pngSha256, quality: c.quality.verdict as "pass" | "warn" }));
  if (!built.ok) {
    return { ...base, status: "failed", textures, notices: [...base.notices, `The resource pack could not be built for Minecraft ${build.mcVersion}: ${built.error}.`] };
  }
  const pack = built.pack;
  const packSha256 = sha256Hex(pack.zip);

  // 3. host it (immutable, content addressed); 4. the Pack Loader entry
  let url: string | null = null;
  let loader: MbAssets["loader"] = null;
  const notices = [...base.notices];
  const sel = deps.selectStore();
  if (sel.ok) {
    const pub = await publishPack(sel.store, pack.zip, { maxBytes: sel.maxBytes });
    if (pub.ok) {
      url = pub.url;
      const prompt = clip(`${name} uses custom item textures. Accept the pack to see them.`, 300);
      const r = applyPackChange(null, { op: "upsert", namespace: project.namespace, role: PACK_ROLE, sha1: pub.sha1, prompt, required: false }, { urlFor: () => pub.url });
      if (r.ok) loader = { id: r.id, url: pub.url, sha1: pub.sha1, prompt, required: false };
      else notices.push("The pack was published, but its delivery entry could not be prepared.");
    } else notices.push(`The resource pack could not be published (${pub.code}).`);
  } else {
    notices.push("The resource pack is built, but pack delivery to servers is not switched on yet, so players won't see the custom textures yet.");
  }

  // 5. revision + asset rows (idempotent)
  const manifest: ManifestEntry[] = [
    ...(build.jarName && build.jarSha256 ? [{ path: `plugin/${build.jarName}`, sha256: build.jarSha256, role: "artifact" as const }] : []),
    ...ok.map((c) => ({ path: `assets/textures/${c.name}.json`, sha256: c.specSha256, role: "asset" as const })),
    { path: `resourcepack/${pack.sha1}.zip`, sha256: packSha256, role: "resourcePack" as const },
  ];
  let revisionId: string | null = null;
  for (let attempt = 0; attempt < 4 && !revisionId; attempt++) {
    const found = await deps.findRevisionForBuild(project.id, build.id);
    if (found) { revisionId = found.id; break; }
    const head = await deps.headRevisionId(project.id);
    try {
      const rev = await deps.addRevision(project.id, {
        kind: "generated", manifest, modBuildId: build.id, status: "passed", expectedHeadId: head,
        engine: { ...(ar.promptVersion ? { promptVersion: ar.promptVersion } : {}), toolchain: `cyrus-textures ${QUALITY_VERSION} (service ${ar.qualityVersion}); pack format ${pack.packFormat}` },
        message: clip(`${ok.length} custom texture${ok.length > 1 ? "s" : ""}; pack ${pack.sha1.slice(0, 12)}${ar.kept ? " (kept unchanged)" : ""}`, 200),
      });
      revisionId = rev.id;
    } catch (e) {
      if ((e as { code?: string }).code === "stale_head") continue; // someone appended meanwhile: look again
      throw e;
    }
  }
  if (!revisionId) throw new Error("could not record the asset revision (the project kept moving)");
  for (const c of ok) {
    await deps.recordAsset(project.id, {
      revisionId, assetKey: c.name, kind: "texture", sha256: c.specSha256, size: Buffer.byteLength(c.canonical), origin: "generated",
      mime: TEXTURE_SPEC_MIME, path: `assets/textures/${c.name}.json`,
      provenance: { generator: "cyrus-texture-dsl", spec: c.spec, quality: c.quality, pngSha256: c.pngSha256, packSha1: pack.sha1, modBuildId: build.id, kept: ar.kept === true },
    });
  }
  return {
    ...base, status: url ? "ready" : "unhosted", revisionId, textures, notices,
    pack: { sha1: pack.sha1, sha256: packSha256, bytes: pack.bytes, format: pack.packFormat, clientVerified: pack.packClientVerified, url },
    loader,
  };
}

/** Read ModBuild.result.assets defensively (old rows have none). */
export function readBuildAssets(result: unknown): MbAssets | null {
  const a = (result as { assets?: unknown } | null)?.assets as MbAssets | undefined;
  if (!a || typeof a !== "object" || !Array.isArray(a.textures) || typeof a.namespace !== "string") return null;
  return a;
}

