  };
  const ident = packIdentOf(build) ?? (await projectForRootBuild(build.rootBuildId ?? build.id).then((p) => (p ? { namespace: p.namespace, projectId: p.id } : null)));
  if (a.op === "remove") return ident ? removeBuildPack(a.serverId, ident, deps) : null;
  const r = await deliverBuildPack(a.serverId, build, deps);
  // A version without a pack replaced one with a pack: drop the stale entry.
  if (r.ok && r.action === "no_pack" && ident) return removeBuildPack(a.serverId, ident, deps);
  return r;
}
