  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-assets-"));
  const BASE = "https://packs.example.invalid";
  const store = new LocalDiskStore(tmp, BASE);
  const sel = () => ({ ok: true as const, store, maxBytes: 10 * 1024 * 1024 });

  it("ready: pack hosted at its immutable URL, loader entry computed, one revision with jar/spec/pack hashes", async () => {
    const d = memDeps(sel);
    d.mem.projects.set("mbT1", { id: "cp" + "9".repeat(20), namespace: NS, userId: "u1" });
    const a = (await syncBuildAssets(build(), svcResult([fixture("ruby_sword"), HEALTH_POTION]), d))!;
    assert.equal(a.status, "ready", JSON.stringify(a.notices));
    assert.deepEqual(a.textures.map((t) => t.model), [`${NS}:ruby_sword`, `${NS}:health_potion`]);
    assert.equal(a.pack!.url, publicPackUrl(BASE, a.pack!.sha1));
    assert.equal(a.pack!.format, 75);
    assert.equal(a.pack!.clientVerified, false);
    const zip = (await store.read(a.pack!.sha1))!;
    assert.equal(createHash("sha1").update(zip).digest("hex"), a.pack!.sha1, "round trip: the hosted bytes are the pack");
    const files = unzip(zip);
    assert.equal(JSON.parse(files.get(`assets/${NS}/items/ruby_sword.json`)!.toString()).model.model, `${NS}:item/ruby_sword`);
    assert.equal(JSON.parse(files.get("pack.mcmeta")!.toString()).pack.pack_format, 75);
    assert.deepEqual(a.loader, { id: packIdFor(NS, "main"), url: a.pack!.url, sha1: a.pack!.sha1, prompt: "Ruby uses custom item textures. Accept the pack to see them.", required: false });
    assert.equal(d.mem.revisions.length, 1);
    const rev = d.mem.revisions[0].input as { kind: string; status: string; manifest: { path: string; role: string; sha256: string }[]; engine: { promptVersion: string } };
    assert.equal(rev.kind, "generated"); assert.equal(rev.status, "passed");
    assert.deepEqual(rev.manifest.map((m) => m.role).sort(), ["artifact", "asset", "asset", "resourcePack"]);
    assert.equal(rev.manifest.find((m) => m.path === "assets/textures/ruby_sword.json")!.sha256, specSha256(checkSpec(fixture("ruby_sword")).ok ? (checkSpec(fixture("ruby_sword")) as { spec: never }).spec : null!));
    assert.equal(rev.engine.promptVersion, "mb-assets-2026-10-10.1");
    assert.equal(d.mem.assets.size, 2);
    const asset = [...d.mem.assets.values()][0] as { provenance: { quality: { verdict: string }; spec: unknown } };
    assert.equal(asset.provenance.quality.verdict, "pass", "the quality report is stored with the asset");

    // re-sync: same revision, same assets, same pack object
    const again = (await syncBuildAssets(build(), svcResult([fixture("ruby_sword"), HEALTH_POTION]), d))!;
    assert.equal(again.revisionId, a.revisionId);
    assert.equal(d.mem.revisions.length, 1);
    assert.equal(d.mem.assets.size, 2);
    assert.equal(again.pack!.sha1, a.pack!.sha1);
    assert.equal((await store.list()).length, 1);
  });

  it("hosting off -> unhosted (no loader entry, honest notice); preview version -> failed; bad/ugly spec -> dropped", async () => {
    const off = await syncBuildAssets(build({ id: "mbT2", rootBuildId: "mbT2" }), svcResult([fixture("ruby_sword")]), memDeps(() => ({ ok: false, reason: "off" })));
    assert.equal(off!.status, "unhosted");
    assert.equal(off!.loader, null);
    assert.ok(off!.pack && off!.pack.url === null);
    assert.match(off!.notices.join(" "), /not switched on yet/);
    const prev = await syncBuildAssets(build({ id: "mbT3", rootBuildId: "mbT3", mcVersion: "26.2" }), svcResult([fixture("ruby_sword")]), memDeps(sel));
    assert.equal(prev!.status, "failed");
    assert.match(prev!.notices.join(" "), /preview version/);
    const bad = await syncBuildAssets(build({ id: "mbT4", rootBuildId: "mbT4" }), svcResult([fixture("flat_square"), { ...fixture("ruby_sword"), ops: [{ op: "fill", c: "nope" }] }, fixture("ruby_sword")]), memDeps(sel));
    assert.equal(bad!.status, "ready");
    assert.deepEqual(bad!.textures.map((t) => t.name), ["ruby_sword"]);
    assert.deepEqual(bad!.dropped.map((x) => x.name), ["flat_square", "ruby_sword"].slice(0, 2));
  });

  it("namespace mismatch is refused; no assets -> null (nothing recorded)", async () => {
    const d = memDeps(sel);
    const r = await syncBuildAssets(build({ id: "mbT5", rootBuildId: "mbT5" }), svcResult([fixture("ruby_sword")], { namespace: "nx_other000" }), d);
    assert.equal(r!.status, "failed");
    assert.equal(d.mem.revisions.length, 0);
    assert.equal(await syncBuildAssets(build(), null, d), null);
    assert.equal(await syncBuildAssets(build(), svcResult([]), d), null);
  });

  it("delivery is switched off by default and a build without a pack is a no-op", async () => {
    const a = (await syncBuildAssets(build({ id: "mbT6", rootBuildId: "mbT6" }), svcResult([fixture("ruby_sword")]), memDeps(sel)))!;
    const fakeDeps = { managed: null as never, fs: null as never, env: {} };
    assert.deepEqual(await deliverBuildPack("srv1", { id: "mbT6", mcVersion: "1.21.11", result: { assets: a } }, fakeDeps), { ok: true, action: "switched_off", wrote: false, notes: ["custom-texture pack delivery is switched off (CYRUS_MANAGED_PLUGINS_REAL is not 1); the plugin was installed without it"] });
    assert.equal((await deliverBuildPack("srv1", { id: "x", mcVersion: "1.21.11", result: {} }, fakeDeps) as { action: string }).action, "no_pack");
    assert.equal((await removeBuildPack("srv1", { namespace: NS, projectId: a.projectId }, fakeDeps) as { action: string }).action, "switched_off");
    assert.equal(readBuildAssets({ assets: a })!.namespace, NS);
    assert.equal(readBuildAssets({ assets: { nope: 1 } }), null);
  });
});

// ------------------------------------------------------------------------------------------------ mod page
describe("NxLabs mod page lists assets truthfully", () => {
  const a = (over: Partial<MbAssets>): MbAssets => ({ status: "ready", namespace: NS, projectId: "cp" + "1".repeat(20), revisionId: "r", textures: [{ name: "ruby_sword", model: `${NS}:ruby_sword`, specSha256: "a".repeat(64), pngSha256: "b".repeat(64), quality: "pass" }], dropped: [], pack: null, loader: null, notices: [], ...over });
  it("ready / unhosted / failed / dropped lines, always with the Bedrock line", () => {
    assert.deepEqual(assetLines(a({})), ["Includes 1 custom texture; players accept a resource pack on join.", "Bedrock players (Geyser/Floodgate) see vanilla looks: the custom textures are a Java Edition resource pack."]);
    assert.match(assetLines(a({ status: "unhosted" }))[0], /not switched on yet/);
    assert.match(assetLines(a({ status: "failed" }))[0], /could not be built/);
    assert.deepEqual(assetLines(a({ status: "none", textures: [], dropped: [{ name: "x", reason: "y" }] })), ["1 requested texture was left out after failing Nxeon's texture checks."]);
    assert.deepEqual(assetLines(null), []);
  });
  it("buildModDoc carries the lines of the current version only when it has assets", () => {
    const b = (id: string, result: unknown) => ({ id, status: "succeeded", prompt: "p", changeRequest: null, baseBuildId: null, rootBuildId: "m1", mcVersion: "1.21.11", pluginName: "Ruby", version: "1.0.0", jarName: "Ruby.jar", jarSize: 1, result, createdAt: new Date(1), finishedAt: new Date(2) });
    const doc = buildModDoc([b("m1", { summary: null, assets: a({ textures: [a({}).textures[0], { ...a({}).textures[0], name: "ruby_axe" }] }) })])!;
    assert.deepEqual(doc.assets!.textures, ["ruby_sword", "ruby_axe"]);
    assert.equal(doc.assets!.lines[0], "Includes 2 custom textures; players accept a resource pack on join.");
    assert.equal(buildModDoc([b("m1", { summary: null })])!.assets, undefined);
  });
});

