// Cyrus R1 asset slice (pure, no DB, no network, no model): the server-side gate wiring of a build request for every
// plan, the prompt section's presence/absence, the build service's JS validator/renderer/quality vs the TypeScript
// ones on shared fixtures, the quality bar on golden textures, the portal sync (pack build + hosting round trip with
// the local store, idempotency with in-memory engine deps), delivery switches and the mod page lines.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { inflateRawSync } from "node:zlib";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { render } from "../lib/cyrus/textures/render";
import { textureQuality } from "../lib/cyrus/textures/quality";
import { GLOCK } from "../lib/cyrus/textures/sample-glock";
import { FROST_BLADE, HEALTH_POTION } from "../lib/cyrus/textures/sample-items";
import { ASSET_PIPELINE_READY, detectAssetKinds, planBuildAssets, requestedAssetKinds } from "../lib/cyrus/assets/plan";
import { existingAssetKinds, resolveBuildAssets, type AssetRequestDeps } from "../lib/cyrus/assets/request";
import { canonicalJson, specSha256 } from "../lib/cyrus/assets/textures";
import { readBuildAssets, syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { deliverBuildPack, removeBuildPack } from "../lib/cyrus/assets/deliver";
import { assetLines, buildModDoc } from "../lib/cyrus-mods/doc";
import { LocalDiskStore } from "../lib/cyrus/packhost/local";
import { packIdFor } from "../lib/cyrus/packhost/loader-config";
import { publicPackUrl } from "../lib/cyrus/packhost/types";
import type { SvcAssetResult } from "../lib/modbuilder/client";
import type { MbAssets } from "../lib/modbuilder/types";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const TXJS = require("../services/modbuilder/textures.js");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const P = require("../services/modbuilder/prompts.js");

const FIX = path.join(__dirname, "fixtures/cyrus-textures");
const fixture = (n: string) => JSON.parse(fs.readFileSync(path.join(FIX, `${n}.json`), "utf8"));
const NS = "nx_ab12cd34";

// ------------------------------------------------------------------------------------------------ gate wiring
type Calls = { tier: number; find: number; create: number };
function deps(tier: string | Error | null, opts: { project?: { id: string; namespace: string } | null; createFails?: boolean } = {}): AssetRequestDeps & { calls: Calls } {
  const calls: Calls = { tier: 0, find: 0, create: 0 };
  let project = opts.project ?? null;
  return {
    calls,
    tierOf: async () => { calls.tier++; if (tier instanceof Error) throw tier; return tier as string; },
    projectForRootBuild: async () => { calls.find++; return project; },
    createProject: async () => { calls.create++; if (opts.createFails) throw new Error("db down"); project = { id: "cp" + "1".repeat(20), namespace: NS }; return project; },
  };
}
const fresh = { userId: "u1", rootBuildId: "mb1", change: false, mcVersion: "1.21.11" };

describe("asset gate wiring in the build request (all plans x requested / not)", () => {
  const PLANS: [string, string | Error | null][] = [["free", "free"], ["katara", "katara"], ["saka", "saka"], ["all", "all"], ["yakko (alias of all)", "yakko"], ["unknown string", "platinum"], ["null", null], ["lookup throws", new Error("db")]];
  const REQUESTS: [string, { explicit?: unknown; text: string }][] = [
    ["nothing", { text: "A /spawn command that teleports players to spawn" }],
    ["texture (explicit list)", { explicit: ["texture"], text: "A ruby sword that sets enemies on fire" }],
    ["texture (explicit object)", { explicit: { texture: true }, text: "A ruby sword" }],
    ["texture (words)", { text: "A ruby sword with a custom texture" }],
    ["sound (words)", { text: "A boss that roars with custom sounds" }],
    ["texture + sound", { explicit: ["texture", "sound"], text: "A banshee" }],
  ];
  for (const [pl, tier] of PLANS) for (const [rq, req] of REQUESTS) {
    it(`${pl} x ${rq}`, async () => {
      const d = deps(tier);
      const r = await resolveBuildAssets({ ...fresh, ...req }, d);
      const kinds = requestedAssetKinds({ explicit: req.explicit, text: req.text });
      if (!kinds.length) {
        assert.deepEqual(r, { plan: null, service: null, meta: null });
        assert.deepEqual(d.calls, { tier: 0, find: 0, create: 0 }, "nothing requested: no lookups, no project");
        return;
      }
      assert.equal(d.calls.tier, 1);
      const top = tier === "all" || tier === "yakko";
      const wantTexture = top && kinds.includes("texture");
      assert.equal(r.service?.texture ?? false, wantTexture);
      assert.equal(r.service?.sound ?? false, false, "sound pipeline is not built yet: never sent");
      if (wantTexture) {
        assert.deepEqual(r.service, { texture: true, sound: false, namespace: NS });
        assert.equal(d.calls.create, 1);
        assert.equal(r.meta?.namespace, NS);
      } else {
        assert.equal(r.service, null, "refused: the service request stays byte-identical (no assets field)");
        assert.equal(d.calls.create, 0, "no project for a refused request");
      }
      // every refused kind has exactly one customer-visible reason
      const refused = kinds.filter((k) => !(k === "texture" && wantTexture));
      assert.equal(r.meta!.notices.length, refused.length, JSON.stringify(r.meta));
      for (const n of r.meta!.notices) assert.match(n, /needs the|couldn't confirm|not built into Cyrus yet/);
      if (kinds.includes("sound") && (tier === "saka" || top)) assert.ok(r.meta!.notices.some((n) => /Custom sounds are not built into Cyrus yet/.test(n)));
      if (kinds.includes("texture") && !top) assert.ok(r.meta!.notices.some((n) => /(All models plan|couldn't confirm your Cyrus plan)/.test(n)));
    });
  }

  it("the client cannot force assets: an explicit request on a lower plan is refused server side", async () => {
    const r = await resolveBuildAssets({ ...fresh, explicit: { texture: true, sound: true, namespace: "nx_hacked00" }, text: "x" }, deps("katara"));
    assert.equal(r.service, null);
    assert.deepEqual(r.meta!.allowed, []);
  });
  it("1.21.1 has no item models: textures refused with a clear message even on the top plan", async () => {
    const r = await resolveBuildAssets({ ...fresh, mcVersion: "1.21.1", explicit: ["texture"], text: "x" }, deps("all"));
    assert.equal(r.service, null);
    assert.match(r.meta!.notices[0], /need Minecraft 1\.21\.4 or newer.*1\.21\.1/);
  });
  it("a change reuses the chain's project; a project that cannot be created fails closed", async () => {
    const d = deps("all", { project: { id: "cp" + "2".repeat(20), namespace: "nx_zz99yy88" } });
    const r = await resolveBuildAssets({ ...fresh, change: true, explicit: ["texture"], text: "make it blue" }, d);
    assert.equal(r.service?.namespace, "nx_zz99yy88");
    assert.equal(d.calls.create, 0);
    const f = await resolveBuildAssets({ ...fresh, explicit: ["texture"], text: "x" }, deps("all", { createFails: true }));
    assert.equal(f.service, null);
    assert.match(f.meta!.notices.at(-1)!, /couldn't set up this mod's asset project/);
  });
  it("keeping is never gated: a change to a mod with textures on a lower plan says they are kept", async () => {
    const existing = existingAssetKinds({ assets: { textures: [{ name: "ruby_sword" }] } });
    assert.deepEqual(existing, ["texture"]);
    const r = await resolveBuildAssets({ ...fresh, change: true, text: "add a /heal command", existing }, deps("katara"));
    assert.equal(r.service, null);
    assert.match(r.meta!.notices[0], /existing custom textures are kept exactly as they are/);
  });
  it("detects asset words with the adapter's route rules (never non-asset rules)", () => {
    assert.deepEqual(detectAssetKinds("a retextured diamond sword"), ["texture"]);
    assert.deepEqual(detectAssetKinds("new sounds for the boss"), ["sound"]);
    assert.deepEqual(detectAssetKinds("custom blocks and a minimap"), []);
    assert.deepEqual(ASSET_PIPELINE_READY, { texture: true, sound: false });
    assert.equal(planBuildAssets({ plan: "all", requested: ["texture"], mcVersion: "26.2" }).allowed.texture, true, "26.2 has item models (it is simply not buildable yet)");
  });
});

// ------------------------------------------------------------------------------------------------ prompts
describe("build service prompt: texture section only when allowed", () => {
  it("absent without textures (byte-identical), present and appended with them", () => {
    for (const v of ["1.21.11", "1.21.4"]) {
      const base = P.systemPrompt(v);
      assert.equal(P.systemPrompt(v, {}), base);
      assert.equal(P.systemPrompt(v, { textures: false }), base);
      assert.doesNotMatch(base, /CUSTOM TEXTURES|assets\/textures/);
      const tex = P.systemPrompt(v, { textures: true });
      assert.ok(tex.startsWith(base) && tex.length > base.length);
      assert.match(tex, /CUSTOM TEXTURES/);
      assert.match(tex, /setItemModel\(new NamespacedKey\("<namespace>", "<texture name>"\)\)/);
      assert.match(tex, /never send resource packs from the plugin/);
      assert.match(tex, /Original art only/);
    }
  });
  it("the user turn names the reserved namespace only for texture builds", () => {
    const a = P.initialPrompt({ prompt: "p", mcVersion: "1.21.11" }, "/w", []);
    const b = P.initialPrompt({ prompt: "p", mcVersion: "1.21.11", assets: { texture: false, namespace: NS } }, "/w", []);
    const c = P.initialPrompt({ prompt: "p", mcVersion: "1.21.11", assets: { texture: true, namespace: NS } }, "/w", []);
    assert.equal(a, b);
    assert.doesNotMatch(a, /namespace/);
    assert.match(c, new RegExp(`reserved namespace is ${NS}`));
    assert.match(P.repairPrompt("asset", "- x", "/w"), /texture specs need fixing/);
  });
  it("the example spec in the prompt is the golden ruby sword and passes every check", () => {
    const ex = JSON.parse(fs.readFileSync(path.join(__dirname, "../services/modbuilder/texture-example.json"), "utf8"));
    assert.deepEqual(ex, fixture("ruby_sword"));
    const c = checkSpec(ex);
    assert.ok(c.ok);
    if (c.ok) assert.equal(textureQuality(render(c.spec)).verdict, "pass");
  });
});

// ------------------------------------------------------------------------------------------------ JS == TS
const INVALID: unknown[] = [
  null, 7, "x", {}, { name: "A", size: 16, palette: { a: "#000000" }, ops: [{ op: "fill", c: "a" }] },
  { name: "ok_name", size: 24, palette: { a: "#000000" }, ops: [{ op: "fill", c: "a" }] },
  { name: "ok_name", size: 16, palette: {}, ops: [{ op: "fill", c: "a" }] },
  { name: "ok_name", size: 16, palette: { A: "#000000" }, ops: [{ op: "fill", c: "A" }] },
  { name: "ok_name", size: 16, palette: { a: "red" }, ops: [{ op: "fill", c: "a" }] },
  { name: "ok_name", size: 16, palette: { a: "#000000" }, ops: [] },
  { name: "ok_name", size: 16, palette: { a: "#000000" }, ops: [{ op: "fill", c: "b" }] },
  { name: "ok_name", size: 16, palette: { a: "#000000" }, ops: [{ op: "exec", cmd: "id" }] },
  { name: "ok_name", size: 16, palette: { a: "#000000" }, ops: [{ op: "px", x: 99, y: 1, c: "a" }] },
  { name: "ok_name", size: 16, palette: { a: "#000000" }, ops: [{ op: "poly", pts: [[1, 1], [2, 2]], c: "a" }] },
  { name: "ok_name", size: 16, palette: { a: "#000000" }, ops: [{ op: "noise", amount: 61 }] },
  { name: "ok_name", size: 16, palette: { a: "#000000" }, ops: [{ op: "circle", x: 1, y: 1, r: 17, c: "a" }] },
  { name: "ok_name", size: 16, palette: { a: "#000000" }, ops: Array.from({ length: 401 }, () => ({ op: "px", x: 1, y: 1, c: "a" })) },
  { name: "ok_name", size: 16, palette: Object.fromEntries(Array.from({ length: 25 }, (_, i) => [`c${i}`, "#000000"])), ops: [{ op: "fill", c: "c0" }] },
];
const VALID = () => [
  ...fs.readdirSync(FIX).filter((f) => f.endsWith(".json")).sort().map((f) => JSON.parse(fs.readFileSync(path.join(FIX, f), "utf8"))),
  GLOCK, FROST_BLADE, HEALTH_POTION,
  { name: "mirror_edge", size: 16, palette: { a: "#ff0000", b: "#220000" }, mirror: true, ops: [{ op: "rect", x: 1, y: 2, w: 30, h: 4, c: "a" }, { op: "noise", amount: 30, seed: 3, x: 8, y: 8, w: 16, h: 16 }, { op: "gradient", x: 0, y: 6, w: 16, h: 5, c1: "a", c2: "b", dir: "h" }, { op: "circle", x: 8, y: 12, r: 3, c: "b", ring: true }, { op: "shade" }, { op: "outline", c: "b" }] },
];

describe("build service validator/renderer/quality == the TypeScript ones", () => {
  it("checkSpec gives identical results on valid and invalid inputs", () => {
    for (const s of [...VALID(), ...INVALID]) assert.deepEqual(TXJS.checkSpec(s), checkSpec(s), JSON.stringify(s).slice(0, 120));
  });
  it("render is byte-identical and the quality reports are identical", () => {
    for (const s of VALID()) {
      const c = checkSpec(s);
      assert.ok(c.ok);
      if (!c.ok) continue;
      const ts = render(c.spec), js = TXJS.render(c.spec);
      assert.equal(Buffer.from(js.px).equals(Buffer.from(ts.px)), true, c.spec.name);
      assert.deepEqual(TXJS.textureQuality(js), textureQuality(ts), c.spec.name);
      assert.equal(TXJS.canonicalJson(c.spec), canonicalJson(c.spec));
    }
  });
});

// ------------------------------------------------------------------------------------------------ quality bar
describe("quality bar v1 on golden textures", () => {
  const verdict = (s: unknown) => { const c = checkSpec(s); assert.ok(c.ok); return c.ok ? textureQuality(render(c.spec)) : null!; };
  const st = (q: ReturnType<typeof textureQuality>, id: string) => q.checks.find((c) => c.id === id)!.status;
  it("passes the vanilla-style ruby sword and the potion", () => {
    assert.equal(verdict(fixture("ruby_sword")).verdict, "pass");
    assert.equal(verdict(HEALTH_POTION).verdict, "pass");
  });
  it("warns on busy palettes (the Glock: 49 colours at 32 px) without failing", () => {
    const q = verdict(GLOCK);
    assert.equal(q.verdict, "warn");
    assert.equal(st(q, "palette_size"), "warn");
  });
  it("fails a solid square, an empty canvas and a noisy gradient blob", () => {
    const sq = verdict(fixture("flat_square"));
    assert.equal(st(sq, "transparency"), "fail"); assert.equal(st(sq, "contrast"), "fail");
    assert.equal(st(verdict(fixture("tiny_dot")), "transparency"), "fail");
    const no = verdict(fixture("noisy_orb"));
    assert.equal(no.verdict, "fail"); assert.equal(st(no, "palette_size"), "fail");
  });
  it("the lookalike check is an honest stub", () => {
    const q = verdict(fixture("ruby_sword"));
    assert.deepEqual(q.checks.find((c) => c.id === "vanilla_lookalike")!.status, "not_run");
  });
  it("golden render hash of the ruby sword (renderer changes must be deliberate)", () => {
    const c = checkSpec(fixture("ruby_sword"));
    assert.ok(c.ok);
    if (c.ok) assert.equal(createHash("sha256").update(render(c.spec).px).digest("hex"), GOLDEN_RUBY);
  });
});
const GOLDEN_RUBY = "__GOLDEN__";

// ------------------------------------------------------------------------------------------------ sync (pack + hosting)
type Mem = { revisions: { id: string; projectId: string; modBuildId: string | null; seq: number; input: unknown }[]; assets: Map<string, unknown>; projects: Map<string, { id: string; namespace: string; userId: string }> };
function memDeps(store: AssetSyncDeps["selectStore"], mem: Mem = { revisions: [], assets: new Map(), projects: new Map() }) {
  const d: AssetSyncDeps & { mem: Mem } = {
    mem,
    selectStore: store,
    projectForRootBuild: async (root) => mem.projects.get(root) ?? null,
    createProject: async (i) => { const p = { id: "cp" + "9".repeat(20), namespace: NS, userId: i.userId }; mem.projects.set(i.rootBuildId, p); return p; },
    findRevisionForBuild: async (projectId, modBuildId) => mem.revisions.find((r) => r.projectId === projectId && r.modBuildId === modBuildId) ?? null,
    headRevisionId: async (projectId) => mem.revisions.filter((r) => r.projectId === projectId).at(-1)?.id ?? null,
    addRevision: async (projectId, input) => { const r = { id: `rev${mem.revisions.length + 1}`, projectId, modBuildId: input.modBuildId ?? null, seq: mem.revisions.length + 1, input }; mem.revisions.push(r); return r; },
    recordAsset: async (projectId, a) => { const k = `${projectId}|${a.kind}|${a.assetKey}|${a.sha256}`; if (!mem.assets.has(k)) mem.assets.set(k, a); return mem.assets.get(k); },
  };
  return d;
}
const svcResult = (specs: unknown[], extra: Partial<SvcAssetResult> = {}): SvcAssetResult => ({
  namespace: NS, promptVersion: "mb-assets-2026-10-10.1", qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [],
  textures: specs.map((s) => ({ name: (s as { name: string }).name, path: `assets/textures/${(s as { name: string }).name}.json`, sha256: TXJS.canonicalJson(s), spec: s, quality: null })),
  ...extra,
});
const build = (over: Partial<Parameters<typeof syncBuildAssets>[0]> = {}) => ({ id: "mbT1", userId: "u1", rootBuildId: "mbT1", mcVersion: "1.21.11", pluginName: "Ruby", jarName: "Ruby-1.0.0.jar", jarSha256: "a".repeat(64), ...over });
const unzip = (z: Buffer) => {
  const eocd = z.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
  const n = z.readUInt16LE(eocd + 10); let p = z.readUInt32LE(eocd + 16); const out = new Map<string, Buffer>();
  for (let i = 0; i < n; i++) {
    const csz = z.readUInt32LE(p + 20), nl = z.readUInt16LE(p + 28), el = z.readUInt16LE(p + 30), cl = z.readUInt16LE(p + 32), off = z.readUInt32LE(p + 42);
    const name = z.subarray(p + 46, p + 46 + nl).toString("utf8");
    const lnl = z.readUInt16LE(off + 26), lel = z.readUInt16LE(off + 28);
    out.set(name, inflateRawSync(z.subarray(off + 30 + lnl + lel, off + 30 + lnl + lel + csz))); p += 46 + nl + el + cl;
  }
  return out;
};

describe("portal sync: pack build + hosting round trip (local store), revision + assets, idempotent", () => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-assets-"));
  const BASE = "https://packs.example.invalid";
  const store = new LocalDiskStore(tmp, BASE);
  const sel = () => ({ ok: true as const, store, maxBytes: 10 * 1024 * 1024 });

  it("ready: pack hosted at its immutable URL, loader entry computed, one revision with jar/spec/pack hashes", async () => {
    const d = memDeps(sel);
    d.mem.projects.set("mbT1", { id: "cp" + "9".repeat(20), namespace: NS, userId: "u1" });
    const a = (await syncBuildAssets(build(), svcResult([fixture("ruby_sword"), HEALTH_POTION]), d))!;
    assert.equal(a.status, "ready", JSON.stringify(a.notices));
    assert.deepEqual(a.textures.map((t) => t.model), [`${NS}:ruby_sword`, `${NS}:health_potion`]);
    assert.equal(a.pack!.url, publicPackUrl(BASE, a.pack!.sha1));
    assert.equal(a.pack!.format, 75);
    assert.equal(a.pack!.clientVerified, false);
    const zip = (await store.read(a.pack!.sha1))!;
    assert.equal(createHash("sha1").update(zip).digest("hex"), a.pack!.sha1, "round trip: the hosted bytes are the pack");
    const files = unzip(zip);
    assert.equal(JSON.parse(files.get(`assets/${NS}/items/ruby_sword.json`)!.toString()).model.model, `${NS}:item/ruby_sword`);
    assert.equal(JSON.parse(files.get("pack.mcmeta")!.toString()).pack.pack_format, 75);
    assert.deepEqual(a.loader, { id: packIdFor(NS, "main"), url: a.pack!.url, sha1: a.pack!.sha1, prompt: "Ruby uses custom item textures. Accept the pack to see them.", required: false });
    assert.equal(d.mem.revisions.length, 1);
    const rev = d.mem.revisions[0].input as { kind: string; status: string; manifest: { path: string; role: string; sha256: string }[]; engine: { promptVersion: string } };
    assert.equal(rev.kind, "generated"); assert.equal(rev.status, "passed");
    assert.deepEqual(rev.manifest.map((m) => m.role).sort(), ["artifact", "asset", "asset", "resourcePack"]);
    assert.equal(rev.manifest.find((m) => m.path === "assets/textures/ruby_sword.json")!.sha256, specSha256(checkSpec(fixture("ruby_sword")).ok ? (checkSpec(fixture("ruby_sword")) as { spec: never }).spec : null!));
    assert.equal(rev.engine.promptVersion, "mb-assets-2026-10-10.1");
    assert.equal(d.mem.assets.size, 2);
    const asset = [...d.mem.assets.values()][0] as { provenance: { quality: { verdict: string }; spec: unknown } };
    assert.equal(asset.provenance.quality.verdict, "pass", "the quality report is stored with the asset");

    // re-sync: same revision, same assets, same pack object
    const again = (await syncBuildAssets(build(), svcResult([fixture("ruby_sword"), HEALTH_POTION]), d))!;
    assert.equal(again.revisionId, a.revisionId);
    assert.equal(d.mem.revisions.length, 1);
    assert.equal(d.mem.assets.size, 2);
    assert.equal(again.pack!.sha1, a.pack!.sha1);
    assert.equal((await store.list()).length, 1);
  });

  it("hosting off -> unhosted (no loader entry, honest notice); preview version -> failed; bad/ugly spec -> dropped", async () => {
    const off = await syncBuildAssets(build({ id: "mbT2", rootBuildId: "mbT2" }), svcResult([fixture("ruby_sword")]), memDeps(() => ({ ok: false, reason: "off" })));
    assert.equal(off!.status, "unhosted");
    assert.equal(off!.loader, null);
    assert.ok(off!.pack && off!.pack.url === null);
    assert.match(off!.notices.join(" "), /not switched on yet/);
    const prev = await syncBuildAssets(build({ id: "mbT3", rootBuildId: "mbT3", mcVersion: "26.2" }), svcResult([fixture("ruby_sword")]), memDeps(sel));
    assert.equal(prev!.status, "failed");
    assert.match(prev!.notices.join(" "), /preview version/);
    const bad = await syncBuildAssets(build({ id: "mbT4", rootBuildId: "mbT4" }), svcResult([fixture("flat_square"), { ...fixture("ruby_sword"), ops: [{ op: "fill", c: "nope" }] }, fixture("ruby_sword")]), memDeps(sel));
    assert.equal(bad!.status, "ready");
    assert.deepEqual(bad!.textures.map((t) => t.name), ["ruby_sword"]);
    assert.deepEqual(bad!.dropped.map((x) => x.name), ["flat_square", "ruby_sword"].slice(0, 2));
  });

  it("namespace mismatch is refused; no assets -> null (nothing recorded)", async () => {
    const d = memDeps(sel);
    const r = await syncBuildAssets(build({ id: "mbT5", rootBuildId: "mbT5" }), svcResult([fixture("ruby_sword")], { namespace: "nx_other000" }), d);
    assert.equal(r!.status, "failed");
    assert.equal(d.mem.revisions.length, 0);
    assert.equal(await syncBuildAssets(build(), null, d), null);
    assert.equal(await syncBuildAssets(build(), svcResult([]), d), null);
  });

  it("delivery is switched off by default and a build without a pack is a no-op", async () => {
    const a = (await syncBuildAssets(build({ id: "mbT6", rootBuildId: "mbT6" }), svcResult([fixture("ruby_sword")]), memDeps(sel)))!;
    const fakeDeps = { managed: null as never, fs: null as never, env: {} };
    assert.deepEqual(await deliverBuildPack("srv1", { id: "mbT6", mcVersion: "1.21.11", result: { assets: a } }, fakeDeps), { ok: true, action: "switched_off", wrote: false, notes: ["custom-texture pack delivery is switched off (CYRUS_MANAGED_PLUGINS_REAL is not 1); the plugin was installed without it"] });
    assert.equal((await deliverBuildPack("srv1", { id: "x", mcVersion: "1.21.11", result: {} }, fakeDeps) as { action: string }).action, "no_pack");
    assert.equal((await removeBuildPack("srv1", { namespace: NS, projectId: a.projectId }, fakeDeps) as { action: string }).action, "switched_off");
    assert.equal(readBuildAssets({ assets: a })!.namespace, NS);
    assert.equal(readBuildAssets({ assets: { nope: 1 } }), null);
  });
});

// ------------------------------------------------------------------------------------------------ mod page
describe("NxLabs mod page lists assets truthfully", () => {
  const a = (over: Partial<MbAssets>): MbAssets => ({ status: "ready", namespace: NS, projectId: "cp" + "1".repeat(20), revisionId: "r", textures: [{ name: "ruby_sword", model: `${NS}:ruby_sword`, specSha256: "a".repeat(64), pngSha256: "b".repeat(64), quality: "pass" }], dropped: [], pack: null, loader: null, notices: [], ...over });
  it("ready / unhosted / failed / dropped lines, always with the Bedrock line", () => {
    assert.deepEqual(assetLines(a({})), ["Includes 1 custom texture; players accept a resource pack on join.", "Bedrock players (Geyser/Floodgate) see vanilla looks: the custom textures are a Java Edition resource pack."]);
    assert.match(assetLines(a({ status: "unhosted" }))[0], /not switched on yet/);
    assert.match(assetLines(a({ status: "failed" }))[0], /could not be built/);
    assert.deepEqual(assetLines(a({ status: "none", textures: [], dropped: [{ name: "x", reason: "y" }] })), ["1 requested texture was left out after failing Nxeon's texture checks."]);
    assert.deepEqual(assetLines(null), []);
  });
  it("buildModDoc carries the lines of the current version only when it has assets", () => {
    const b = (id: string, result: unknown) => ({ id, status: "succeeded", prompt: "p", changeRequest: null, baseBuildId: null, rootBuildId: "m1", mcVersion: "1.21.11", pluginName: "Ruby", version: "1.0.0", jarName: "Ruby.jar", jarSize: 1, result, createdAt: new Date(1), finishedAt: new Date(2) });
    const doc = buildModDoc([b("m1", { summary: null, assets: a({ textures: [a({}).textures[0], { ...a({}).textures[0], name: "ruby_axe" }] }) })])!;
    assert.deepEqual(doc.assets!.textures, ["ruby_sword", "ruby_axe"]);
    assert.equal(doc.assets!.lines[0], "Includes 2 custom textures; players accept a resource pack on join.");
    assert.equal(buildModDoc([b("m1", { summary: null })])!.assets, undefined);
  });
});

