import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/**
 * Cyrus R1 asset slice against a THROWAWAY Postgres: the build-request gate with the REAL plan lookup (CyrusPlan +
 * admin override through tokens/access tierOf) and the real project store; the portal sync with the real engine-core
 * store and the local pack store (re-sync and concurrent syncs record exactly one revision); pack delivery with the
 * real managed-plugin service (memory installer, local fake guest). No server, no model, no network.
 *
 * Opt-in and fail-closed: runs only when CYRUS_ASSETS_DB_TEST=1 and DATABASE_URL is a node-2 agent database.
 *   devhost db push && devhost run --lock -- env CYRUS_ASSETS_DB_TEST=1 npx tsx --test test/cyrus-assets-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_ASSETS_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_ASSETS_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
const uniq = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const uid = (n: string) => `cyas-${uniq}-${n}`;
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-assets-db-"));
const env = { CYRUS_PACK_STORE: "local", CYRUS_PACK_LOCAL_DIR: path.join(tmp, "packs"), CYRUS_PACK_PUBLIC_BASE: "https://packs.example.invalid" };
const fixture = (n: string) => JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/cyrus-textures", `${n}.json`), "utf8"));

before(async () => {
  if (!safe) return;
  db = (await import("../lib/db.ts")).db;
  const end = new Date(Date.now() + 20 * 86400_000);
  for (const t of ["katara", "saka", "all"]) {
    await db.cyrusPlan.create({ data: { userId: uid(t), stripeCustomerId: `cus_${uid(t)}`, stripeSubscriptionId: `sub_${uid(t)}`, tier: t, priceTier: t, status: "active", currentPeriodEnd: end } });
  }
  await db.cyrusPlan.create({ data: { userId: uid("lapsed"), stripeCustomerId: `cus_${uid("lapsed")}`, stripeSubscriptionId: `sub_${uid("lapsed")}`, tier: "all", priceTier: "all", status: "canceled", currentPeriodEnd: new Date(Date.now() - 86400_000) } });
  await db.cyrusTokenAccount.create({ data: { userId: uid("comp"), tierOverride: "all" } });
});
after(async () => {
  if (!safe) return;
  const projects = await db.cyrusProject.findMany({ where: { userId: { startsWith: `cyas-${uniq}-` } }, select: { id: true } });
  const ids = projects.map((p) => p.id);
  await db.cyrusProjectAsset.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusRevision.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusProject.deleteMany({ where: { id: { in: ids } } });
  await db.cyrusServerManagedPlugin.deleteMany({ where: { serverId: { startsWith: `cyas-${uniq}-` } } });
  await db.cyrusPlan.deleteMany({ where: { userId: { startsWith: `cyas-${uniq}-` } } });
  await db.cyrusTokenAccount.deleteMany({ where: { userId: { startsWith: `cyas-${uniq}-` } } });
  await db.$disconnect();
  fs.rmSync(tmp, { recursive: true, force: true });
});

