    const TXJS = require("../services/modbuilder/textures.js");
    const root = `mb${uniq}dlv`;
    const p = await createProject({ userId: uid("all"), game: "minecraft", rootBuildId: root });
    const ar = { namespace: p.namespace, promptVersion: null, qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], textures: [{ name: "ruby_sword", path: "x", sha256: "", spec: TXJS.checkSpec(fixture("ruby_sword")).spec, quality: null }] };
    const a = (await syncBuildAssets({ id: root, userId: uid("all"), rootBuildId: root, mcVersion: "1.21.11", pluginName: "Ruby", jarName: null, jarSha256: null }, ar, defaultAssetSyncDeps(env)))!;
    const guestRoot = path.join(tmp, "guest");
    fs.mkdirSync(path.join(guestRoot, "opt/mc"), { recursive: true });
    fs.writeFileSync(path.join(guestRoot, "opt/mc/server.properties"), "motd=x\n");
    const inst = memoryInstaller();
    const deps = { managed: { db, installer: inst, catalog: loadCatalog() }, fs: new LocalGuestFs(guestRoot), env: { CYRUS_MANAGED_PLUGINS_REAL: "1" } };
    const server = uid("srv");
    const b = { id: root, mcVersion: "1.21.11", result: { assets: a } };
    const d1 = await deliverBuildPack(server, b, deps);
    assert.deepEqual(d1.ok && [d1.action, d1.wrote, d1.loader], ["added", true, "installed"], JSON.stringify(d1));
    const cfg = await readLoaderConfig(deps.fs);
    assert.ok(cfg.ok && cfg.config);
    if (cfg.ok) assert.deepEqual(cfg.config!.packs.map((x) => [x.id, x.url, x.sha1, x.required]), [[a.loader!.id, a.loader!.url, a.pack!.sha1, false]]);
