 * Cyrus R1 Test Flight fixture: does exactly what the build prompt tells a generated mod to do for a custom texture,
 * meta.setItemModel(new NamespacedKey(namespace, name)), then reads the key back from the item, so a flight proves the
 * registry-backed key works on the real Paper server (no client involved).
 */
public class ItemModelPlugin extends JavaPlugin {
    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
